/* ═══════════════════════════════════════════════════════════════════════════
 * rigcom_ui.c — Túnel WebSocket único + UI 3D del ecosistema
 *
 * Piel viva del backend. Ni CLI ni dashboard de texto: RigCom Visor 3D Pro
 * embebido — diseño soberano del Arquitecto (RigCom v35 visor3d pro).
 *
 *   φ = 1.6180339887498948482
 *   Puerto UI canónico: 61803  (φ × 10000)
 *
 * Diseño:
 *   • rigcom_ui_serve(port) arranca UN rig_ws_server (wsserver.c),
 *     instala la escena 3D embebida como dashboard, y bloquea hasta stop.
 *   • Todos los subsistemas del binario emiten al MISMO canal:
 *       rigcom_ui_publish(json, len)       broadcast a la UI
 *       rigcom_ui_send_to(fd, json, len)   dirigido
 *       rigcom_ui_emit_event(...)          contrato canónico RIGCOM
 *
 * Cero dependencias externas. UI PRO del arquitecto (menú PHI-NAV con 27
 * ítems: Inicio, Editor, Registros, Ajustes, Android, Nodos, Oráculo,
 * Portal, Puente, Terminal, Depurar, Caché, RigScript, Blindaje, Motor,
 * Canvas, Tubería, Neural, Sanar, Grafo, ADB, Pipeline, Doctor, Watch,
 * AAR, Rigadiel, RigArt).
 * ═══════════════════════════════════════════════════════════════════════════ */

