    "  send({cmd:'rigart_transition',\n"
    "    type:parseInt(_raGet('ra-trans-type')?.value||0),\n"
    "    dur:parseFloat(_raGet('ra-trans-dur')?.value||0.6),\n"
    "    ease:parseInt(_raGet('ra-trans-ease')?.value||1)\n"
    "  });\n"
    "  addLog('⬡ rigart_transition → '+(_raGet('ra-trans-type')?.value||0));\n"
    "}\n"
    "\n"
    "// §29 Comportamientos\n"
    "function rigartBehavior(){\n"
    "  if(!wsOk()){addLog('WS desconectado','err');return;}\n"
    "  send({cmd:'rigart_behavior',\n"
    "    type:parseInt(_raGet('ra-behav-type')?.value||0),\n"
    "    strength:parseFloat(_raGet('ra-behav-strength')?.value||0.5),\n"
    "    damping:0.15,\n"
    "    selector:_raGet('ra-behav-selector')?.value||'.card'\n"
    "  });\n"
    "  addLog('⬡ rigart_behavior → '+(_raGet('ra-behav-type')?.value||0));\n"
    "}\n"
    "\n"
    "// §30 Color P3\n"
    "function rigartColorP3(){\n"
    "  if(!wsOk()){addLog('WS desconectado','err');return;}\n"
    "  var L=parseFloat(_raGet('ra-color-L')?.value||0.7);\n"
    "  var C=parseFloat(_raGet('ra-color-C')?.value||0.2);\n"
    "  var h=parseFloat(_raGet('ra-color-h')?.value||45);\n"
    "  var prev=_raGet('ra-color-preview');\n"
    "  if(prev) prev.style.background='oklch('+L+' '+C+' '+h+')';\n"
    "  send({cmd:'rigart_color_p3', L:L, C:C, h:h});\n"
    "  addLog('⬡ rigart_color_p3 → oklch('+L+' '+C+' '+h+')');\n"
    "}\n"
    "\n"
    "// §30 Gradiente perceptual\n"
    "function rigartGradient(){\n"
    "  if(!wsOk()){addLog('WS desconectado','err');return;}\n"
    "  send({cmd:'rigart_gradient_perc',\n"
    "    L0:0.5, C0:0.2, h0:parseFloat(_raGet('ra-grad-h0')?.value||30),\n"
    "    L1:0.8, C1:0.15, h1:parseFloat(_raGet('ra-grad-h1')?.value||210),\n"
    "    angle:parseFloat(_raGet('ra-grad-angle')?.value||135)\n"
    "  });\n"
    "  addLog('⬡ rigart_gradient_perc → ángulo '+(_raGet('ra-grad-angle')?.value||135)+'°');\n"
    "}\n"
    "\n"
    "// §31 Texturas PBR\n"
    "function rigartTexture(){\n"
    "  if(!wsOk()){addLog('WS desconectado','err');return;}\n"
    "  send({cmd:'rigart_texture',\n"
    "    type:parseInt(_raGet('ra-tex-type')?.value||0),\n"
    "    scale:parseFloat(_raGet('ra-tex-scale')?.value||1.0),\n"
    "    roughness:parseFloat(_raGet('ra-tex-rough')?.value||0.5),\n"
    "    metallic:parseFloat(_raGet('ra-tex-metal')?.value||0.8)\n"
    "  });\n"
    "  addLog('⬡ rigart_texture → '+(_raGet('ra-tex-type')?.value||0));\n"
    "}\n"
    "\n"
    "// §32 Micro-interacciones\n"
    "function rigartMicro(){\n"
    "  if(!wsOk()){addLog('WS desconectado','err');return;}\n"
    "  send({cmd:'rigart_micro',\n"
    "    type:parseInt(_raGet('ra-micro-type')?.value||0),\n"
    "    dur:parseFloat(_raGet('ra-micro-dur')?.value||0.2),\n"
    "    color:0xFFD700,\n"
    "    selector:_raGet('ra-micro-selector')?.value||'.btn'\n"
    "  });\n"
    "  addLog('⬡ rigart_micro → '+(_raGet('ra-micro-type')?.value||0));\n"
    "}\n"
    "\n"
    "// Color preview live update\n"
    "['ra-color-L','ra-color-C','ra-color-h'].forEach(function(id){\n"
    "  document.addEventListener('DOMContentLoaded',function(){\n"
    "    var el=document.getElementById(id);\n"
    "    if(el) el.addEventListener('input',function(){\n"
    "      var L=parseFloat(_raGet('ra-color-L')?.value||0.7);\n"
    "      var C=parseFloat(_raGet('ra-color-C')?.value||0.2);\n"
    "      var h=parseFloat(_raGet('ra-color-h')?.value||45);\n"
    "      var prev=_raGet('ra-color-preview');\n"
    "      if(prev) prev.style.background='oklch('+L+' '+C+' '+h+')';\n"
    "    });\n"
    "  });\n"
    "});\n"
    "\n"
    "// Handler WS para rigart_result en el switch existente — agregado al patcher\n"
    "// FIX #3: Segunda declaración de handleNewEventsV15 causaba recursión infinita.\n"
    "// La función original (línea ~4645) ya existe — aquí solo se EXTIENDE, no se redefine.\n"
    "// Se reemplaza el cuerpo con un wrapper limpio que NO causa loop.\n"
    "var _handleNewEventsCore = handleNewEventsV15; // alias del original antes de sobrescribir\n"
    "handleNewEventsV15 = function(d){\n"
    "  var ev = d.ev||d.cmd||'';\n"
    "  // RigArt result (ok:true, cmd:rigart_*, certeza, data)\n"
    "  if((ev==='' && d.cmd && d.cmd.indexOf('rigart_')===0 && d.ok!==undefined) ||\n"
    "     ev==='rigart_result' || ev==='rigart_done' ||\n"
    "     (d.cmd && d.cmd.indexOf('rigart_')===0)){\n"
    "    _raResult(d); return true;\n"
    "  }\n"
    "  return _handleNewEventsCore(d);\n"
    "};\n"
    "\n"
    "</script>\n"
    "\n"
    "<script>\n"
    "/* ══════════════════════════════════════════════════════════════════\n"
    "   RIgArt Visor 3D v4.0 — Motor WebGL2 Soberano · SIN THREE.JS\n"
    "   φ = 1.6180339887498948482 · P(A) ∈ {0,1}\n"
    "   Autor: Richard Felipe Urbina\n"
    "   Integrado en RigCom v16 — UI idéntica al pixel a rigart_visor3d_v4\n"
    "   ══════════════════════════════════════════════════════════════════ */\n"
    "(function() {\n"
    "'use strict';\n"
    "\n"
    "let nearPlane = 0.001, farPlane = 1000;\n"
    "\n"
    "const PHI = 1.6180339887498948482;\n"
    "\n"
    "// ── Math utils ─────────────────────────────────────────────────\n"
    "const mat4 = {\n"
    "  create() { const m=new Float32Array(16); m[0]=m[5]=m[10]=m[15]=1; return m; },\n"
    "  perspective(out, fov, asp, near, far) {\n"
    "    const f=1/Math.tan(fov/2), nf=1/(near-far);\n"
    "    out[0]=f/asp; out[1]=0; out[2]=0; out[3]=0;\n"
    "    out[4]=0; out[5]=f; out[6]=0; out[7]=0;\n"
    "    out[8]=0; out[9]=0; out[10]=(far+near)*nf; out[11]=-1;\n"
    "    out[12]=0; out[13]=0; out[14]=2*far*near*nf; out[15]=0;\n"
    "    return out;\n"
    "  },\n"
    "  identity(out) { out.fill(0); out[0]=out[5]=out[10]=out[15]=1; return out; },\n"
    "  multiply(out, a, b) {\n"
    "    for(let i=0;i<4;i++) for(let j=0;j<4;j++) {\n"
    "      let s=0; for(let k=0;k<4;k++) s+=a[i*4+k]*b[k*4+j]; out[i*4+j]=s;\n"
    "    } return out;\n"
    "  },\n"
    "  lookAt(out, eye, center, up) {\n"
    "    let fx=center[0]-eye[0], fy=center[1]-eye[1], fz=center[2]-eye[2];\n"
    "    let len=Math.sqrt(fx*fx+fy*fy+fz*fz); if(!len) return mat4.identity(out);\n"
    "    fx/=len; fy/=len; fz/=len;\n"
    "    let sx=fy*up[2]-fz*up[1], sy=fz*up[0]-fx*up[2], sz=fx*up[1]-fy*up[0];\n"
    "    len=Math.sqrt(sx*sx+sy*sy+sz*sz); if(!len){sx=sy=sz=0;}else{sx/=len;sy/=len;sz/=len;}\n"
    "    const ux=sy*fz-sz*fy, uy=sz*fx-sx*fz, uz=sx*fy-sy*fx;\n"
    "    out[0]=sx; out[1]=ux; out[2]=-fx; out[3]=0;\n"
    "    out[4]=sy; out[5]=uy; out[6]=-fy; out[7]=0;\n"
    "    out[8]=sz; out[9]=uz; out[10]=-fz; out[11]=0;\n"
    "    out[12]=-(sx*eye[0]+sy*eye[1]+sz*eye[2]);\n"
    "    out[13]=-(ux*eye[0]+uy*eye[1]+uz*eye[2]);\n"
    "    out[14]=fx*eye[0]+fy*eye[1]+fz*eye[2];\n"
    "    out[15]=1;\n"
    "    return out;\n"
    "  },\n"
    "  rotY(out, a) {\n"
    "    const c=Math.cos(a),s=Math.sin(a);\n"
    "    out[0]=c; out[1]=0; out[2]=-s; out[3]=0;\n"
    "    out[4]=0; out[5]=1; out[6]=0; out[7]=0;\n"
    "    out[8]=s; out[9]=0; out[10]=c; out[11]=0;\n"
    "    out[12]=0; out[13]=0; out[14]=0; out[15]=1;\n"
    "    return out;\n"
    "  }\n"
    "};\n"
    "\n"
    "// ── Shaders ─────────────────────────────────────────────────────\n"
    "const VS_PBR = `#version 300 es\n"
    "precision highp float;\n"
    "layout(location=0) in vec3 aPos;\n"
    "layout(location=1) in vec3 aNorm;\n"
    "layout(location=2) in vec2 aUV;\n"
    "uniform mat4 uMVP;\n"
    "uniform mat4 uModel;\n"
    "uniform mat4 uNormMat;\n"
    "uniform float uExposure;\n"
    "out vec3 vPos;\n"
    "out vec3 vNorm;\n"
    "out vec2 vUV;\n"
    "void main(){\n"
    "  vec4 wp=uModel*vec4(aPos,1.0);\n"
    "  vPos=wp.xyz;\n"
    "  vNorm=normalize((uNormMat*vec4(aNorm,0.0)).xyz);\n"
    "  vUV=aUV;\n"
    "  gl_Position=uMVP*wp;\n"
    "}`;\n"
    "\n"
    "const FS_PBR = `#version 300 es\n"
    "precision highp float;\n"
    "in vec3 vPos;\n"
    "in vec3 vNorm;\n"
    "in vec2 vUV;\n"
    "uniform vec3 uCamPos;\n"
    "uniform float uRoughness;\n"
    "uniform float uMetalness;\n"
    "uniform vec3  uAlbedo;\n"
    "uniform float uOpacity;\n"
    "uniform int   uHasTex;\n"
    "uniform sampler2D uBaseTex;\n"
    "uniform float uExposure;\n"
    "uniform float uAmbInt;\n"
    "uniform vec3 uKeyDir; uniform vec3 uKeyCol; uniform float uKeyInt;\n"
    "uniform vec3 uFillDir; uniform vec3 uFillCol; uniform float uFillInt;\n"
    "uniform vec3 uRimDir; uniform vec3 uRimCol; uniform float uRimInt;\n"
    "uniform vec3  uFogColor;\n"
    "uniform float uFogDensity;\n"
    "uniform float uFogEnabled;\n"
    "out vec4 fragColor;\n"
    "\n"
    "const float PI=3.14159265;\n"
    "\n"
    "float D_GGX(float NdotH,float r){\n"
    "  float a=r*r; float a2=a*a;\n"
    "  float d=NdotH*NdotH*(a2-1.0)+1.0;\n"
    "  return a2/(PI*d*d+1e-7);\n"
    "}\n"
    "float G_Smith(float NdotV,float NdotL,float r){\n"
    "  float k=(r+1.0)*(r+1.0)/8.0;\n"
    "  float g1=NdotV/(NdotV*(1.0-k)+k);\n"
    "  float g2=NdotL/(NdotL*(1.0-k)+k);\n"
    "  return g1*g2;\n"
    "}\n"
    "vec3 F_Schlick(float cosT,vec3 F0){\n"
    "  return F0+(1.0-F0)*pow(clamp(1.0-cosT,0.0,1.0),5.0);\n"
    "}\n"
    "vec3 cookTorrance(vec3 N,vec3 V,vec3 L,vec3 lc,float li,vec3 alb,float met,float rou){\n"
    "  vec3 H=normalize(V+L);\n"
    "  float NdotL=max(dot(N,L),0.0);\n"
    "  float NdotV=max(dot(N,V),0.001);\n"
    "  float NdotH=max(dot(N,H),0.0);\n"
    "  float VdotH=max(dot(V,H),0.0);\n"
    "  vec3 F0=mix(vec3(0.04),alb,met);\n"
    "  float D=D_GGX(NdotH,rou);\n"
    "  float G=G_Smith(NdotV,NdotL,rou);\n"
    "  vec3  F=F_Schlick(VdotH,F0);\n"
    "  vec3 spec=D*G*F/(4.0*NdotV*NdotL+1e-7);\n"
    "  vec3 kd=(1.0-F)*(1.0-met);\n"
    "  return (kd*alb/PI+spec)*lc*li*NdotL;\n"
    "}\n"
    "vec3 acesFilmic(vec3 x){\n"
    "  float a=2.51,b=0.03,c=2.43,d=0.59,e=0.14;\n"
    "  return clamp((x*(a*x+b))/(x*(c*x+d)+e),0.0,1.0);\n"
    "}\n"
    "void main(){\n"
    "  vec3 N=normalize(vNorm);\n"
    "  vec3 V=normalize(uCamPos-vPos);\n"
    "  vec3 alb = (uHasTex!=0) ? pow(texture(uBaseTex, vUV).rgb, vec3(2.2)) : uAlbedo;\n"
    "  float met=uMetalness, rou=uRoughness;\n"
    "  vec3 amb=uAmbInt*alb*vec3(0.08,0.07,0.1);\n"
    "  vec3 col=amb;\n"
    "  col+=cookTorrance(N,V,normalize(-uKeyDir),uKeyCol,uKeyInt,alb,met,rou);\n"
    "  col+=cookTorrance(N,V,normalize(-uFillDir),uFillCol,uFillInt,alb,met,rou);\n"
    "  col+=cookTorrance(N,V,normalize(-uRimDir),uRimCol,uRimInt,alb,met,rou);\n"
    "  col*=uExposure;\n"
    "  col=acesFilmic(col);\n"
    "  col=pow(col,vec3(1.0/2.2));\n"
    "  if (uFogEnabled > 0.5) {\n"
    "    float dist = length(vPos - uCamPos);\n"
    "    float fogF = 1.0 - exp(-uFogDensity * uFogDensity * dist * dist);\n"
    "    col = mix(col, uFogColor, clamp(fogF, 0.0, 0.8));\n"
    "  }\n"
    "  fragColor=vec4(col,uOpacity);\n"
    "}`;\n"
    "\n"
    "const VS_FLAT = `#version 300 es\n"
    "precision mediump float;\n"
    "layout(location=0) in vec3 aPos;\n"
    "uniform mat4 uMVP;\n"
    "uniform vec4 uColor;\n"
    "out vec4 vColor;\n"
    "void main(){ vColor=uColor; gl_Position=uMVP*vec4(aPos,1.0); }`;\n"
    "\n"
    "const FS_FLAT = `#version 300 es\n"
    "precision mediump float;\n"
    "in vec4 vColor;\n"
    "out vec4 fragColor;\n"
    "void main(){ fragColor=vColor; }`;\n"
    "\n"
    "const VS_NORMALS = `#version 300 es\n"
    "precision highp float;\n"
    "layout(location=0) in vec3 aPos;\n"
    "layout(location=1) in vec3 aNorm;\n"
    "uniform mat4 uMVP;\n"
    "uniform mat4 uModel;\n"
    "out vec3 vNorm;\n"
    "void main(){ vNorm=normalize((uModel*vec4(aNorm,0.0)).xyz); gl_Position=uMVP*uModel*vec4(aPos,1.0); }`;\n"
    "\n"
    "const FS_NORMALS = `#version 300 es\n"
    "precision mediump float;\n"
    "in vec3 vNorm;\n"
    "out vec4 fragColor;\n"
    "void main(){ fragColor=vec4(vNorm*0.5+0.5,1.0); }`;\n"
    "\n"
    "const VS_GRID = `#version 300 es\n"
    "precision mediump float;\n"
    "layout(location=0) in vec3 aPos;\n"
    "uniform mat4 uMVP;\n"
    "void main(){ gl_Position=uMVP*vec4(aPos,1.0); }`;\n"
    "\n"
    "const FS_GRID = `#version 300 es\n"
    "precision mediump float;\n"
    "out vec4 fragColor;\n"
    "void main(){ fragColor=vec4(0.12,0.10,0.16,0.55); }`;\n"
    "\n"
    "// ── GL helpers ──────────────────────────────────────────────────\n"
    "function mkShader(gl, type, src) {\n"
    "  const s = gl.createShader(type);\n"
    "  gl.shaderSource(s, src); gl.compileShader(s);\n"
    "  if (!gl.getShaderParameter(s, gl.COMPILE_STATUS)) { console.error(gl.getShaderInfoLog(s)); return null; }\n"
    "  return s;\n"
    "}\n"
    "function mkProg(gl, vs, fs) {\n"
    "  const p = gl.createProgram();\n"
    "  gl.attachShader(p, mkShader(gl, gl.VERTEX_SHADER, vs));\n"
    "  gl.attachShader(p, mkShader(gl, gl.FRAGMENT_SHADER, fs));\n"
    "  gl.linkProgram(p);\n"
    "  if (!gl.getProgramParameter(p, gl.LINK_STATUS)) { console.error(gl.getProgramInfoLog(p)); return null; }\n"
    "  return p;\n"
    "}\n"
    "function uLoc(gl, p, name) { return gl.getUniformLocation(p, name); }\n"
    "\n"
    "// ── State ────────────────────────────────────────────────────────\n"
    "const cnv   = document.getElementById('rv3d-canvas');\n"
    "const wrap  = document.getElementById('rv3d-canvas-wrap');\n"
    "let gl;\n"
    "\n"
    "try {\n"
    "  gl = cnv.getContext('webgl2', { antialias:true, alpha:true, preserveDrawingBuffer:true, powerPreference:'high-performance' });\n"
    "} catch(e) { gl = null; }\n"
    "\n"
    "if (!gl) {\n"
    "  document.getElementById('rv3d-open-screen').innerHTML = '<p style=\"color:#c8a45a;font-family:JetBrains Mono;font-size:9px;letter-spacing:2px;text-align:center;padding:20px\">WebGL2 no disponible en este entorno</p>';\n"
    "}\n"
    "\n"
    "let progPBR, progFlat, progNorm, progGrid;\n"
    "if (gl) {\n"
    "  progPBR   = mkProg(gl, VS_PBR,     FS_PBR);\n"
    "  progFlat  = mkProg(gl, VS_FLAT,    FS_FLAT);\n"
    "  progNorm  = mkProg(gl, VS_NORMALS, FS_NORMALS);\n"
    "  progGrid  = mkProg(gl, VS_GRID,    FS_GRID);\n"
    "}\n"
    "\n"
    "// ── Camera state ─────────────────────────────────────────────────\n"
    "const sph    = { theta: 0.5, phi: 1.25, radius: 5 };\n"
    "const target = [0, 0, 0];\n"
    "let autoRotate = true;\n"
    "let rotSpeed   = 0.003;\n"
    "let fovDeg     = 42;\n"
    "let exposure   = 1.1;\n"
    "let bgColor    = [3/255, 2/255, 8/255];\n"
    "let showGrid   = true;\n"
    "let showGround = true;\n"
    "let fogEnabled = true;\n"
    "let fogDensity = 0.025;\n"
    "let shadowEnabled = true;\n"
    "\n"
    "// Lights\n"
    "const lights = {\n"
    "  amb:  { int: 0.5 },\n"
    "  key:  { dir: [4, 8, 5],  col: [1.0, 0.98, 0.94], int: 1.2 },\n"
    "  fill: { dir: [-5, 2, -3], col: [0.53, 0.60, 0.80], int: 0.4 },\n"
    "  rim:  { dir: [0, -3, -6], col: [0.79, 0.66, 0.30], int: 0.3 }\n"
    "};\n"
    "\n"
    "// Material override\n"
    "const matState = {\n"
    "  mode: 'original',\n"
    "  roughness: 0.5, metalness: 0.0,\n"
    "  color: [1,1,1], opacity: 1.0\n"
    "};\n"
    "\n"
    "// ── Geometry buffers ─────────────────────────────────────────────\n"
    "let gridBuf, groundBuf, groundNorm;\n"
    "let meshes = [];        // {vao, indexBuf, indexCount, material, origColor, bounds}\n"
    "let glbMeshes = [];     // raw data from parsed GLB\n"
    "let glbAnims  = [];\n"
    "let modelLoaded = false;\n"
    "let sceneCenter = [0,0,0];\n"
    "let sceneDiam   = 1;\n"
    "\n"
    "function initScene() {\n"
    "  if (!gl) return;\n"
    "  // Build grid lines\n"
    "  const gridVerts = [];\n"
    "  const N = 20, step = 1;\n"
    "  for(let i=-N;i<=N;i++){\n"
    "    gridVerts.push(i*step, 0, -N*step, i*step, 0, N*step);\n"
    "    gridVerts.push(-N*step, 0, i*step, N*step, 0, i*step);\n"
    "  }\n"
    "  gridBuf = gl.createBuffer();\n"
    "  gl.bindBuffer(gl.ARRAY_BUFFER, gridBuf);\n"
    "  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(gridVerts), gl.STATIC_DRAW);\n"
    "\n"
    "  // Ground plane\n"
    "  const gv = [-30,0,-30, 30,0,-30, 30,0,30, -30,0,-30, 30,0,30, -30,0,30];\n"
    "  groundBuf = gl.createBuffer();\n"
    "  gl.bindBuffer(gl.ARRAY_BUFFER, groundBuf);\n"
    "  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(gv), gl.STATIC_DRAW);\n"
    "}\n"
    "\n"
    "if (gl) initScene();\n"
    "\n"
    "function getCamPos() {\n"
    "  return [\n"
    "    target[0] + sph.radius * Math.sin(sph.phi) * Math.sin(sph.theta),\n"
    "    target[1] + sph.radius * Math.cos(sph.phi),\n"
    "    target[2] + sph.radius * Math.sin(sph.phi) * Math.cos(sph.theta)\n"
    "  ];\n"
    "}\n"
    "\n"
    "function resize3D() {\n"
    "  if (!gl) return;\n"
    "  const w = wrap.clientWidth, h = wrap.clientHeight;\n"
    "  cnv.width = w * Math.min(devicePixelRatio, 2.5);\n"
    "  cnv.height = h * Math.min(devicePixelRatio, 2.5);\n"
    "  gl.viewport(0, 0, cnv.width, cnv.height);\n"
    "}\n"
    "if (gl) { resize3D(); new ResizeObserver(resize3D).observe(wrap); }\n"
    "\n"
    "// ── Render loop ──────────────────────────────────────────────────\n"
    "let lastTime = 0, fpsFrames = 0, fpsLast = performance.now();\n"
    "let animTime = 0;\n"
    "let animPlaying = true, animLooping = true;\n"
    "let currentAnimDuration = 0;\n"
    "let wireMode = false;\n"
    "let drawCallCount = 0;\n"
    "let frameCounter = 0;\n"
    "\n"
    "function hexToRGB(hex) {\n"
    "  const h = hex.replace('#','');\n"
    "  return [parseInt(h.slice(0,2),16)/255, parseInt(h.slice(2,4),16)/255, parseInt(h.slice(4,6),16)/255];\n"
    "}\n"
    "\n"
    "function renderFrame(ts) {\n"
    "  if (!gl) return;\n"
    "  requestAnimationFrame(renderFrame);\n"
    "\n"
    "  const dt = Math.min((ts - lastTime) / 1000, 0.05);\n"
    "  lastTime = ts;\n"
    "\n"
    "  if (autoRotate && modelLoaded) { sph.theta += rotSpeed * dt * 60 * 0.05; }\n"
    "  if (animPlaying && currentAnimDuration > 0) {\n"
    "    animTime += dt;\n"
    "    if (animTime > currentAnimDuration) {\n"
    "      if (animLooping) animTime %= currentAnimDuration;\n"
    "      else { animTime = currentAnimDuration; animPlaying = false; }\n"
    "    }\n"
    "    const pct = (animTime / currentAnimDuration * 100).toFixed(1);\n"
    "    const el = document.getElementById('rv3d-anim-prog');\n"
    "    if (el) el.style.width = pct + '%';\n"
    "    const tel = document.getElementById('rv3d-anim-time');\n"
    "    if (tel) tel.textContent = animTime.toFixed(1) + 's';\n"
    "  }\n"
    "\n"
    "  // Clear\n"
    "  gl.clearColor(bgColor[0], bgColor[1], bgColor[2], 1);\n"
    "  gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);\n"
    "  gl.enable(gl.DEPTH_TEST);\n"
    "  gl.depthFunc(gl.LEQUAL);\n"
    "  gl.enable(gl.BLEND);\n"
    "  gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);\n"
    "\n"
    "  const w = cnv.width, h = cnv.height;\n"
    "  const cam = getCamPos();\n"
    "  const proj = mat4.perspective(mat4.create(), fovDeg * Math.PI/180, w/h, nearPlane, farPlane);\n"
    "  const view = mat4.lookAt(mat4.create(), cam, target, [0,1,0]);\n"
    "  const vp   = mat4.multiply(mat4.create(), proj, view);\n"
    "\n"
    "  drawCallCount = 0;\n"
    "\n"
    "  // Grid\n"
    "  if (showGrid) {\n"
    "    gl.useProgram(progFlat);\n"
    "    const model = mat4.identity(mat4.create());\n"
    "    const mvp   = mat4.multiply(mat4.create(), vp, model);\n"
    "    gl.uniformMatrix4fv(uLoc(gl,progFlat,'uMVP'), false, mvp);\n"
    "    gl.uniform4f(uLoc(gl,progFlat,'uColor'), 0.12, 0.10, 0.16, 0.6);\n"
    "    gl.bindBuffer(gl.ARRAY_BUFFER, gridBuf);\n"
    "    gl.enableVertexAttribArray(0);\n"
    "    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 0, 0);\n"
    "    gl.drawArrays(gl.LINES, 0, 164);\n"
    "    drawCallCount++;\n"
    "  }\n"
    "\n"
    "  // Ground\n"
    "  if (showGround && modelLoaded) {\n"
    "    gl.useProgram(progFlat);\n"
    "    const model = mat4.identity(mat4.create());\n"
    "    model[13] = -sceneDiam * 0.5;\n"
    "    const mvp = mat4.multiply(mat4.create(), vp, model);\n"
    "    gl.uniformMatrix4fv(uLoc(gl,progFlat,'uMVP'), false, mvp);\n"
    "    gl.uniform4f(uLoc(gl,progFlat,'uColor'), 0.03, 0.025, 0.05, 0.7);\n"
    "    gl.bindBuffer(gl.ARRAY_BUFFER, groundBuf);\n"
    "    gl.enableVertexAttribArray(0);\n"
    "    gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 0, 0);\n"
    "    gl.drawArrays(gl.TRIANGLES, 0, 6);\n"
    "    drawCallCount++;\n"
    "  }\n"
    "\n"
    "  // Model meshes\n"
    "  if (modelLoaded && meshes.length) {\n"
    "    const mode = matState.mode;\n"
    "\n"
    "    for (const m of meshes) {\n"
    "      if (!m.visible) continue;\n"
    "      if (!m.vao && !m.vbuf) continue;\n"
    "\n"
    "      let prog = (mode === 'normals') ? progNorm : progPBR;\n"
    "      gl.useProgram(prog);\n"
    "\n"
    "      const model  = mat4.identity(mat4.create());\n"
    "      // Explode: translate each mesh away from scene center\n"
    "      if (explodeAmount > 0 && m.bounds) {\n"
    "        const mc = m.bounds.min.map((v,i) => (v + m.bounds.max[i]) * 0.5);\n"
    "        const dir = normalize3([mc[0]-sceneCenter[0], mc[1]-sceneCenter[1], mc[2]-sceneCenter[2]]);\n"
    "        model[12] = dir[0] * explodeAmount * sceneDiam * 0.4;\n"
    "        model[13] = dir[1] * explodeAmount * sceneDiam * 0.4;\n"
    "        model[14] = dir[2] * explodeAmount * sceneDiam * 0.4;\n"
    "      }\n"
    "      const normM  = mat4.identity(mat4.create()); // simplified, no non-uniform scale\n"
    "      const mvp    = mat4.multiply(mat4.create(), vp, model);\n"
    "\n"
    "      if (mode === 'normals') {\n"
    "        gl.uniformMatrix4fv(uLoc(gl,prog,'uMVP'),   false, mvp);\n"
    "        gl.uniformMatrix4fv(uLoc(gl,prog,'uModel'), false, model);\n"
    "      } else {\n"
    "        // PBR uniforms\n"
    "        const alb = (mode === 'override' || mode === 'unlit') ? matState.color : (m.color || [0.78, 0.65, 0.35]);\n"
    "        const met = (mode === 'override') ? matState.metalness : (m.metalness ?? 0.0);\n"
    "        const rou = (mode === 'override') ? matState.roughness : (m.roughness ?? 0.5);\n"
    "        const op  = (mode === 'override') ? matState.opacity   : 1.0;\n"
    "        const amb = (mode === 'unlit') ? 3.0 : lights.amb.int;\n"
    "\n"
    "        gl.uniformMatrix4fv(uLoc(gl,prog,'uMVP'),     false, mvp);\n"
    "        gl.uniformMatrix4fv(uLoc(gl,prog,'uModel'),   false, model);\n"
    "        gl.uniformMatrix4fv(uLoc(gl,prog,'uNormMat'), false, normM);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uCamPos'),  cam);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uRoughness'), rou);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uMetalness'), met);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uAlbedo'),   alb);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uOpacity'),  op);\n"
    "        // Texture\n"
    "        const hasTex = (mode !== 'override' && mode !== 'normals' && mode !== 'unlit') && !!m.glTex;\n"
    "        gl.uniform1i(uLoc(gl,prog,'uHasTex'), hasTex ? 1 : 0);\n"
    "        gl.uniform1i(uLoc(gl,prog,'uBaseTex'), 0);\n"
    "        gl.activeTexture(gl.TEXTURE0);\n"
    "        if (hasTex) { gl.bindTexture(gl.TEXTURE_2D, m.glTex); }\n"
    "        else { gl.bindTexture(gl.TEXTURE_2D, null); }\n"
    "        gl.uniform1f(uLoc(gl,prog,'uExposure'), exposure);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uAmbInt'),   amb);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uKeyDir'),  lights.key.dir);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uKeyCol'),  lights.key.col);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uKeyInt'),   lights.key.int);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uFillDir'), lights.fill.dir);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uFillCol'), lights.fill.col);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uFillInt'),  lights.fill.int);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uRimDir'),  lights.rim.dir);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uRimCol'),  lights.rim.col);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uRimInt'),   lights.rim.int);\n"
    "        gl.uniform3fv(uLoc(gl,prog,'uFogColor'), bgColor);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uFogDensity'), fogDensity);\n"
    "        gl.uniform1f(uLoc(gl,prog,'uFogEnabled'), fogEnabled ? 1.0 : 0.0);\n"
    "      }\n"
    "\n"
    "      // Bind geometry\n"
    "      gl.bindBuffer(gl.ARRAY_BUFFER, m.vbuf);\n"
    "      // layout: pos(3)+norm(3)+uv(2) = 8 floats = 32 bytes\n"
    "      gl.enableVertexAttribArray(0);\n"
    "      gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 32, 0);\n"
    "      gl.enableVertexAttribArray(1);\n"
    "      gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 32, 12);\n"
    "      gl.enableVertexAttribArray(2);\n"
    "      gl.vertexAttribPointer(2, 2, gl.FLOAT, false, 32, 24);\n"
    "\n"
    "      if (wireMode) {\n"
    "        gl.useProgram(progFlat);\n"
    "        gl.uniformMatrix4fv(uLoc(gl,progFlat,'uMVP'), false, mvp);\n"
    "        gl.uniform4f(uLoc(gl,progFlat,'uColor'), 0.78, 0.65, 0.35, 0.7);\n"
    "        gl.bindBuffer(gl.ARRAY_BUFFER, m.vbuf);\n"
    "        gl.enableVertexAttribArray(0);\n"
    "        gl.vertexAttribPointer(0, 3, gl.FLOAT, false, 32, 0);\n"
    "      }\n"
    "\n"
    "      if (m.ibuf) {\n"
    "        gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, m.ibuf);\n"
    "        if (wireMode) gl.drawElements(gl.LINES, m.indexCount, gl.UNSIGNED_INT, 0);\n"
    "        else gl.drawElements(gl.TRIANGLES, m.indexCount, gl.UNSIGNED_INT, 0);\n"
    "      } else {\n"
    "        const cnt = m.vertCount || 0;\n"
    "        if (wireMode) gl.drawArrays(gl.LINES, 0, cnt);\n"
    "        else gl.drawArrays(gl.TRIANGLES, 0, cnt);\n"
    "      }\n"
    "      drawCallCount++;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  // FPS\n"
    "  fpsFrames++;\n"
    "  if (ts - fpsLast >= 1000) {\n"
    "    const fps = Math.round(fpsFrames * 1000 / (ts - fpsLast));\n"
    "    fpsFrames = 0; fpsLast = ts;\n"
    "    const fe = document.getElementById('rv3d-fps');\n"
    "    if (fe) fe.textContent = fps + ' fps';\n"
    "    const sf = document.getElementById('rv3d-stat-fps');\n"
    "    if (sf) sf.textContent = fps;\n"
    "  }\n"
    "  frameCounter++;\n"
    "  if (frameCounter % 30 === 0) {\n"
    "    const sd = document.getElementById('rv3d-stat-draws');\n"
    "    if (sd) sd.textContent = drawCallCount;\n"
    "  }\n"
    "}\n"
    "\n"
    "if (gl) requestAnimationFrame(renderFrame);\n"
    "\n"
    "// ── GLB Parser (binary glTF) ─────────────────────────────────────\n"
    "function parseGLB(buffer) {\n"
    "  const view = new DataView(buffer);\n"
    "  const magic = view.getUint32(0, true);\n"
    "  if (magic !== 0x46546C67) throw new Error('Not a GLB file');\n"
    "  const version = view.getUint32(4, true);\n"
    "  let offset = 12;\n"
    "  let jsonChunk = null, binChunk = null;\n"
    "  while (offset < buffer.byteLength) {\n"
    "    const chunkLen  = view.getUint32(offset, true);\n"
    "    const chunkType = view.getUint32(offset+4, true);\n"
    "    const data = buffer.slice(offset+8, offset+8+chunkLen);\n"
    "    if (chunkType === 0x4E4F534A) jsonChunk = data;\n"
    "    if (chunkType === 0x004E4942) binChunk  = data;\n"
    "    offset += 8 + chunkLen;\n"
    "  }\n"
    "  if (!jsonChunk) throw new Error('No JSON chunk');\n"
    "  const gltf = JSON.parse(new TextDecoder().decode(jsonChunk));\n"
    "  return { gltf, bin: binChunk };\n"
    "}\n"
    "\n"
    "function getAccessorData(gltf, bin, accIdx) {\n"
    "  if (accIdx === undefined || accIdx === null) return null;\n"
    "  const acc  = gltf.accessors[accIdx];\n"
    "  const bv   = gltf.bufferViews[acc.bufferView];\n"
    "  const bvOffset = (bv.byteOffset || 0);\n"
    "  const accOffset = (acc.byteOffset || 0);\n"
    "  const start = bvOffset + accOffset;\n"
    "  const compCount = { SCALAR:1, VEC2:2, VEC3:3, VEC4:4, MAT2:4, MAT3:9, MAT4:16 };\n"
    "  const n = acc.count * (compCount[acc.type] || 1);\n"
    "  const slice = bin ? bin.slice(start, start + n * 4) : new ArrayBuffer(0);\n"
    "  if (acc.componentType === 5126) return new Float32Array(slice);\n"
    "  if (acc.componentType === 5125) return new Uint32Array(slice);\n"
    "  if (acc.componentType === 5123) return new Uint16Array(slice);\n"
    "  if (acc.componentType === 5121) return new Uint8Array(slice);\n"
    "  return new Float32Array(slice);\n"
    "}\n"
    "\n"
    "function buildMeshBuffers(gltf, bin) {\n"
    "  const result = [];\n"
    "  if (!gltf.meshes) return result;\n"
    "  let totalTris = 0, totalMeshes = 0;\n"
    "  const matSet = new Set(), texSet = new Set();\n"
    "\n"
    "  for (const mesh of gltf.meshes) {\n"
    "    for (const prim of (mesh.primitives || [])) {\n"
    "      const pos  = getAccessorData(gltf, bin, prim.attributes?.POSITION);\n"
    "      const norm = getAccessorData(gltf, bin, prim.attributes?.NORMAL);\n"
    "      const uv   = getAccessorData(gltf, bin, prim.attributes?.TEXCOORD_0);\n"
    "      const idx  = getAccessorData(gltf, bin, prim.indices);\n"
    "      if (!pos) continue;\n"
    "\n"
    "      const vertCount = pos.length / 3;\n"
    "      const interleaved = new Float32Array(vertCount * 8);\n"
    "      for (let i = 0; i < vertCount; i++) {\n"
    "        interleaved[i*8+0] = pos[i*3];\n"
    "        interleaved[i*8+1] = pos[i*3+1];\n"
    "        interleaved[i*8+2] = pos[i*3+2];\n"
    "        interleaved[i*8+3] = norm ? norm[i*3]   : 0;\n"
    "        interleaved[i*8+4] = norm ? norm[i*3+1] : 1;\n"
    "        interleaved[i*8+5] = norm ? norm[i*3+2] : 0;\n"
    "        interleaved[i*8+6] = uv ? uv[i*2]   : 0;\n"
    "        interleaved[i*8+7] = uv ? uv[i*2+1] : 0;\n"
    "      }\n"
    "\n"
    "      const vbuf = gl.createBuffer();\n"
    "      gl.bindBuffer(gl.ARRAY_BUFFER, vbuf);\n"
    "      gl.bufferData(gl.ARRAY_BUFFER, interleaved, gl.STATIC_DRAW);\n"
    "\n"
    "      let ibuf = null, indexCount = 0;\n"
    "      if (idx) {\n"
    "        ibuf = gl.createBuffer();\n"
    "        const idx32 = new Uint32Array(idx.length);\n"
    "        for (let i=0;i<idx.length;i++) idx32[i] = idx[i];\n"
    "        gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibuf);\n"
    "        gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, idx32, gl.STATIC_DRAW);\n"
    "        indexCount = idx.length;\n"
    "        totalTris += idx.length / 3;\n"
    "      } else { totalTris += vertCount / 3; }\n"
    "\n"
    "      // Material color\n"
    "      let mcolor = [0.78, 0.65, 0.35];\n"
    "      let met = 0, rou = 0.5;\n"
    "      if (prim.material !== undefined && gltf.materials) {\n"
    "        const mat = gltf.materials[prim.material];\n"
    "        matSet.add(prim.material);\n"
    "        const pbr = mat?.pbrMetallicRoughness;\n"
    "        if (pbr?.baseColorFactor) {\n"
    "          mcolor = [pbr.baseColorFactor[0], pbr.baseColorFactor[1], pbr.baseColorFactor[2]];\n"
    "        }\n"
    "        met = pbr?.metallicFactor ?? 0;\n"
    "        rou = pbr?.roughnessFactor ?? 0.5;\n"
    "        if (pbr?.baseColorTexture) texSet.add(pbr.baseColorTexture.index);\n"
    "      }\n"
    "\n"
    "      // Bounds\n"
    "      const acc = gltf.accessors[prim.attributes.POSITION];\n"
    "      const bmin = acc.min || [0,0,0];\n"
    "      const bmax = acc.max || [0,0,0];\n"
    "\n"
    "      // Upload baseColor texture if present\n"
    "      let glTex = null;\n"
    "      if (prim.material !== undefined && gltf.materials) {\n"
    "        const mat = gltf.materials[prim.material];\n"
    "        const pbr = mat?.pbrMetallicRoughness;\n"
    "        const bct = pbr?.baseColorTexture;\n"
    "        if (bct !== undefined && bin) {\n"
    "          const texIdx = gltf.textures?.[bct.index];\n"
    "          const imgIdx = texIdx?.source;\n"
    "          const img    = imgIdx !== undefined ? gltf.images?.[imgIdx] : null;\n"
    "          if (img?.bufferView !== undefined) {\n"
    "            const bv2 = gltf.bufferViews[img.bufferView];\n"
    "            const imgSlice = bin.slice(bv2.byteOffset||0, (bv2.byteOffset||0)+(bv2.byteLength||0));\n"
    "            const blob = new Blob([imgSlice], {type: img.mimeType||\"image/png\"});\n"
    "            const url  = URL.createObjectURL(blob);\n"
    "            glTex = gl.createTexture();\n"
    "            const tex  = glTex;\n"
    "            const imgEl = new Image();\n"
    "            imgEl.onload = () => {\n"
    "              gl.bindTexture(gl.TEXTURE_2D, tex);\n"
    "              gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, imgEl);\n"
    "              gl.generateMipmap(gl.TEXTURE_2D);\n"
    "              gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR_MIPMAP_LINEAR);\n"
    "              gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);\n"
    "              gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.REPEAT);\n"
    "              gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.REPEAT);\n"
    "              URL.revokeObjectURL(url);\n"
    "            };\n"
    "            imgEl.src = url;\n"
    "          }\n"
    "        }\n"
    "      }\n"
    "\n"
    "      result.push({\n"
    "        vbuf, ibuf, indexCount, vertCount,\n"
    "        color: mcolor, metalness: met, roughness: rou,\n"
    "        glTex,\n"
    "        visible: true,\n"
    "        name: mesh.name || `Mesh_${totalMeshes}`,\n"
    "        tris: Math.round(idx ? idx.length/3 : vertCount/3),\n"
    "        bounds: { min: bmin, max: bmax }\n"
    "      });\n"
    "      totalMeshes++;\n"
    "    }\n"
    "  }\n"
    "\n"
    "  return { meshList: result, totalTris: Math.round(totalTris), matCount: matSet.size, texCount: texSet.size };\n"
    "}\n"
    "\n"
    "// ── Load file ────────────────────────────────────────────────────\n"
    "function rv3dLoadFile(file) {\n"
    "  document.getElementById('rv3d-open-screen').style.display = 'none';\n"
    "  const ld = document.getElementById('rv3d-loading');\n"
    "  ld.style.display = 'flex'; ld.classList.remove('out');\n"
    "  document.getElementById('rv3d-file-name').textContent = file.name;\n"
    "\n"
    "  const reader = new FileReader();\n"
    "  reader.onprogress = e => {\n"
    "    if (e.total) {\n"
    "      const pct = Math.round(e.loaded/e.total*100);\n"
    "      const lb = document.getElementById('rv3d-load-bar');\n"
    "      if (lb) lb.style.width = pct + '%';\n"
    "      const lp = document.getElementById('rv3d-load-pct');\n"
    "      if (lp) lp.textContent = 'CARGANDO ' + pct + '%';\n"
    "    }\n"
    "  };\n"
    "  reader.onload = e => {\n"
    "    try {\n"
    "      const { gltf, bin } = parseGLB(e.target.result);\n"
    "\n"
    "      // Clear old meshes\n"
    "      meshes.forEach(m => { if(m.vbuf) gl.deleteBuffer(m.vbuf); if(m.ibuf) gl.deleteBuffer(m.ibuf); });\n"
    "      meshes = [];\n"
    "      glbAnims = gltf.animations || [];\n"
    "\n"
    "      const { meshList, totalTris, matCount, texCount } = buildMeshBuffers(gltf, bin);\n"
    "      meshes = meshList;\n"
    "\n"
    "      // Compute scene bounds\n"
    "      let minX=Infinity,minY=Infinity,minZ=Infinity,maxX=-Infinity,maxY=-Infinity,maxZ=-Infinity;\n"
    "      meshes.forEach(m => {\n"
    "        if (m.bounds) {\n"
    "          minX=Math.min(minX,m.bounds.min[0]); minY=Math.min(minY,m.bounds.min[1]); minZ=Math.min(minZ,m.bounds.min[2]);\n"
    "          maxX=Math.max(maxX,m.bounds.max[0]); maxY=Math.max(maxY,m.bounds.max[1]); maxZ=Math.max(maxZ,m.bounds.max[2]);\n"
    "        }\n"
    "      });\n"
    "      if (!isFinite(minX)) { minX=minY=minZ=-1; maxX=maxY=maxZ=1; }\n"
    "      sceneCenter = [(minX+maxX)/2, (minY+maxY)/2, (minZ+maxZ)/2];\n"
    "      const sx = maxX-minX, sy = maxY-minY, sz = maxZ-minZ;\n"
    "      sceneDiam = Math.max(sx, sy, sz);\n"
    "      sph.radius = sceneDiam * 2.4;\n"
    "      target[0]=sceneCenter[0]; target[1]=sceneCenter[1]; target[2]=sceneCenter[2];\n"
    "      animTime = 0;\n"
    "      currentAnimDuration = glbAnims.length > 0 ? (glbAnims[0].duration || 5) : 0;\n"
    "\n"
    "      modelLoaded = true;\n"
    "      autoRotate = document.getElementById('rv3d-autorot')?.checked ?? true;\n"
    "\n"
    "      // Update UI\n"
    "      ld.classList.add('out');\n"
    "      setTimeout(() => { ld.style.display = 'none'; }, 600);\n"
    "\n"
    "      const hu = document.getElementById('rv3d-hud'); if(hu) hu.style.display='block';\n"
    "      const fp = document.getElementById('rv3d-fps'); if(fp) fp.style.display='block';\n"
    "      const fn = v => v >= 1e6 ? (v/1e6).toFixed(1)+'M' : v >= 1e3 ? (v/1e3).toFixed(1)+'K' : v;\n"
    "      const fs = b => b >= 1e6 ? (b/1e6).toFixed(1)+' MB' : (b/1024).toFixed(0)+' KB';\n"
    "\n"
    "      document.getElementById('rv3d-h-meshes').textContent = meshes.length;\n"
    "      document.getElementById('rv3d-h-tris').textContent   = fn(totalTris);\n"
    "      document.getElementById('rv3d-h-mats').textContent   = matCount;\n"
    "      document.getElementById('rv3d-h-anims').textContent  = glbAnims.length || '—';\n"
    "      document.getElementById('rv3d-stat-meshes').textContent = meshes.length;\n"
    "      document.getElementById('rv3d-stat-tris').textContent   = fn(totalTris);\n"
    "      document.getElementById('rv3d-stat-mats').textContent   = matCount;\n"
    "      document.getElementById('rv3d-stat-texs').textContent   = texCount;\n"
    "      document.getElementById('rv3d-stat-anims').textContent  = glbAnims.length;\n"
    "      document.getElementById('rv3d-stat-size').textContent   = fs(file.size);\n"
    "      document.getElementById('rv3d-stat-bx').textContent     = sx.toFixed(2);\n"
    "      document.getElementById('rv3d-stat-by').textContent     = sy.toFixed(2);\n"
    "      document.getElementById('rv3d-stat-bz').textContent     = sz.toFixed(2);\n"
    "      document.getElementById('rv3d-stat-bd').textContent     = sceneDiam.toFixed(2);\n"
    "      document.getElementById('rv3d-file-meta').textContent   = `${meshes.length} mesh · ${fs(file.size)}` + (glbAnims.length ? ` · ${glbAnims.length} anim` : '');\n"
    "\n"
    "      buildRv3dMeshList();\n"
    "      buildRv3dAnimList();\n"
    "      rv3dToast('Modelo cargado · φ');\n"
    "    } catch(err) {\n"
    "      document.getElementById('rv3d-load-pct').textContent = 'ERROR: ' + err.message;\n"
    "      console.error('GLB parse error:', err);\n"
    "    }\n"
    "  };\n"
    "  reader.readAsArrayBuffer(file);\n"
    "}\n"
    "\n"
    "// ── UI builders ─────────────────────────────────────────────────\n"
    "function buildRv3dMeshList() {\n"
    "  const ul = document.getElementById('rv3d-mesh-list');\n"
    "  if (!ul) return;\n"
    "  ul.innerHTML = '';\n"
    "  const cnt = document.getElementById('rv3d-mesh-count');\n"
    "  if (cnt) cnt.textContent = meshes.length + ' meshes';\n"
    "  meshes.forEach((m, i) => {\n"
    "    const el = document.createElement('div');\n"
    "    el.className = 'rv3d-mesh-item' + (m.visible === false ? ' hidden' : '');\n"
    "    el.dataset.meshIdx = i;\n"
    "    const triLabel = m.tris >= 1000 ? (m.tris/1000).toFixed(1)+'K' : (m.tris||0);\n"
    "    el.innerHTML = `\n"
    "      <div class=\"rv3d-mesh-vis${m.visible===false?' off':''}\" title=\"Visibilidad\" data-vis=\"${i}\">\n"
    "        <svg width=\"6\" height=\"6\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\">\n"
    "          <path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/>\n"
    "        </svg>\n"
    "      </div>\n"
    "      <svg width=\"8\" height=\"8\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\" style=\"flex-shrink:0;opacity:.45\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"/></svg>\n"
    "      <span class=\"rv3d-mesh-name\" title=\"${m.name}\">${m.name}</span>\n"
    "      <span class=\"rv3d-mesh-tri\">${triLabel}</span>\n"
    "      <button class=\"rv3d-mesh-iso-btn\" data-iso=\"${i}\" title=\"Aislar\" style=\"background:none;border:none;color:rgba(0,184,204,0.4);font-size:8px;cursor:pointer;padding:0 2px;transition:color .15s;flex-shrink:0\">⊙</button>`;\n"
    "    // Visibility toggle\n"
    "    el.querySelector('[data-vis]').addEventListener('click', e => {\n"
    "      e.stopPropagation();\n"
    "      m.visible = !m.visible;\n"
    "      el.classList.toggle('hidden', !m.visible);\n"
    "      e.currentTarget.classList.toggle('off', !m.visible);\n"
    "    });\n"
    "    // Isolation\n"
    "    el.querySelector('[data-iso]').addEventListener('click', e => {\n"
    "      e.stopPropagation();\n"
    "      const isIso = el.classList.contains('isolated');\n"
    "      document.querySelectorAll('.rv3d-mesh-item').forEach((x, xi) => {\n"
    "        x.classList.remove('isolated');\n"
    "        if (!isIso) {\n"
    "          meshes[xi].visible = (xi === i);\n"
    "          x.classList.toggle('hidden', xi !== i);\n"
    "          x.querySelector('.rv3d-mesh-vis')?.classList.toggle('off', xi !== i);\n"
    "        } else {\n"
    "          meshes[xi].visible = true;\n"
    "          x.classList.remove('hidden');\n"
    "          x.querySelector('.rv3d-mesh-vis')?.classList.remove('off');\n"
    "        }\n"
    "      });\n"
    "      if (!isIso) { el.classList.add('isolated'); rv3dToast('Aislado: ' + m.name); }\n"
    "      else         rv3dToast('Vista completa');\n"
    "    });\n"
    "    // Select\n"
    "    el.addEventListener('click', () => {\n"
    "      document.querySelectorAll('.rv3d-mesh-item').forEach(x => x.classList.remove('selected'));\n"
    "      el.classList.add('selected');\n"
    "    });\n"
    "    ul.appendChild(el);\n"
    "  });\n"
    "}\n"
    "\n"
    "function buildRv3dAnimList() {\n"
    "  const ul = document.getElementById('rv3d-anim-list');\n"
    "  if (!ul) return;\n"
    "  ul.innerHTML = '';\n"
    "  if (!glbAnims.length) {\n"
    "    ul.innerHTML = '<p style=\"font-size:8px;letter-spacing:1.5px;color:rgba(221,213,197,0.25);font-family:JetBrains Mono,monospace\">Sin animaciones</p>';\n"
    "    return;\n"
    "  }\n"
    "  glbAnims.forEach((clip, i) => {\n"
    "    const el = document.createElement('div');\n"
    "    el.className = 'rv3d-anim-item' + (i===0?' playing':'');\n"
    "    el.innerHTML = `<svg width=\"8\" height=\"8\" viewBox=\"0 0 24 24\" fill=\"currentColor\" opacity=\".5\"><polygon points=\"5 3 19 12 5 21 5 3\"/></svg><span>${clip.name||'Clip_'+i}</span><span class=\"rv3d-anim-dur\">${(clip.duration||0).toFixed(2)}s</span>`;\n"
    "    el.addEventListener('click', () => {\n"
    "      document.querySelectorAll('.rv3d-anim-item').forEach(x=>x.classList.remove('playing'));\n"
    "      el.classList.add('playing');\n"
    "      currentAnimDuration = clip.duration || 0;\n"
    "      animTime = 0; animPlaying = true;\n"
    "    });\n"
    "    ul.appendChild(el);\n"
    "  });\n"
    "}\n"
    "\n"
    "// ── Toast ────────────────────────────────────────────────────────\n"
    "let rv3dToastTm;\n"
    "function rv3dToast(msg) {\n"
    "  const el = document.getElementById('rv3d-toast');\n"
    "  if (!el) return;\n"
    "  el.textContent = msg; el.classList.add('show');\n"
    "  clearTimeout(rv3dToastTm);\n"
    "  rv3dToastTm = setTimeout(() => el.classList.remove('show'), 2000);\n"
    "}\n"
    "\n"
    "// ── Controls ─────────────────────────────────────────────────────\n"
    "let rv3dTouches = {}, rv3dLastPinch = null, rv3dLastMid = null;\n"
    "const rv3dCnv = cnv;\n"
    "\n"
    "if (gl) {\n"
    "  rv3dCnv.addEventListener('touchstart', e => {\n"
    "    e.preventDefault(); autoRotate = false;\n"
    "    Array.from(e.touches).forEach(t => rv3dTouches[t.identifier] = {x:t.clientX,y:t.clientY});\n"
    "    if (e.touches.length === 2) {\n"
    "      rv3dLastPinch = Math.hypot(e.touches[0].clientX-e.touches[1].clientX, e.touches[0].clientY-e.touches[1].clientY);\n"
    "      rv3dLastMid   = {x:(e.touches[0].clientX+e.touches[1].clientX)/2, y:(e.touches[0].clientY+e.touches[1].clientY)/2};\n"
    "    }\n"
    "  }, {passive:false});\n"
    "  rv3dCnv.addEventListener('touchend', e => {\n"
    "    e.preventDefault();\n"
    "    Array.from(e.changedTouches).forEach(t => delete rv3dTouches[t.identifier]);\n"
    "    if (e.touches.length < 2) { rv3dLastPinch = null; rv3dLastMid = null; }\n"
    "  }, {passive:false});\n"
    "  rv3dCnv.addEventListener('touchmove', e => {\n"
    "    e.preventDefault();\n"
    "    const ts = Array.from(e.touches);\n"
    "    if (ts.length === 1) {\n"
    "      const p = rv3dTouches[ts[0].identifier];\n"
    "      if (p) {\n"
    "        sph.theta -= (ts[0].clientX - p.x) * 0.011;\n"
    "        sph.phi    = Math.max(0.08, Math.min(Math.PI - 0.08, sph.phi + (ts[0].clientY - p.y) * 0.011));\n"
    "      }\n"
    "      rv3dTouches[ts[0].identifier] = {x:ts[0].clientX, y:ts[0].clientY};\n"
    "    } else if (ts.length === 2) {\n"
    "      const dist = Math.hypot(ts[0].clientX-ts[1].clientX, ts[0].clientY-ts[1].clientY);\n"
    "      const mid  = {x:(ts[0].clientX+ts[1].clientX)/2, y:(ts[0].clientY+ts[1].clientY)/2};\n"
    "      if (rv3dLastPinch !== null) {\n"
    "        sph.radius = Math.max(0.05, Math.min(500, sph.radius * (rv3dLastPinch/dist)));\n"
    "        if (rv3dLastMid) {\n"
    "          const cam = getCamPos();\n"
    "          const right = normalize3(cross3([0,1,0], sub3(cam, target)));\n"
    "          target[0] -= (mid.x - rv3dLastMid.x) * 0.002 * sph.radius * right[0];\n"
    "          target[1] += (mid.y - rv3dLastMid.y) * 0.002 * sph.radius;\n"
    "        }\n"
    "      }\n"
    "      rv3dLastPinch = dist; rv3dLastMid = mid;\n"
    "      ts.forEach(t => rv3dTouches[t.identifier] = {x:t.clientX, y:t.clientY});\n"
    "    }\n"
    "  }, {passive:false});\n"
    "\n"
    "  let rv3dMouseDown = false, rv3dBtn = -1, rv3dLastMouse = {};\n"
    "  rv3dCnv.addEventListener('mousedown', e => { rv3dMouseDown=true; rv3dBtn=e.button; rv3dLastMouse={x:e.clientX,y:e.clientY}; autoRotate=false; e.preventDefault(); });\n"
    "  rv3dCnv.addEventListener('contextmenu', e => e.preventDefault());\n"
    "  window.addEventListener('mouseup', () => rv3dMouseDown=false);\n"
    "  window.addEventListener('mousemove', e => {\n"
    "    if (!rv3dMouseDown) return;\n"
    "    const dx = e.clientX-rv3dLastMouse.x, dy = e.clientY-rv3dLastMouse.y;\n"
    "    if (rv3dBtn===0) { sph.theta-=dx*0.01; sph.phi=Math.max(0.08,Math.min(Math.PI-0.08,sph.phi+dy*0.01)); }\n"
    "    else if (rv3dBtn===2) { target[1]+=dy*0.002*sph.radius; target[0]-=dx*0.001*sph.radius; }\n"
    "    rv3dLastMouse={x:e.clientX,y:e.clientY};\n"
    "  });\n"
    "  rv3dCnv.addEventListener('wheel', e => { sph.radius=Math.max(0.05,sph.radius*(1+e.deltaY*0.001)); }, {passive:true});\n"
    "}\n"
    "\n"
    "// vec3 helpers\n"
    "function sub3(a,b)  { return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }\n"
    "function cross3(a,b){ return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]; }\n"
    "function normalize3(v) { const l=Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])||1; return [v[0]/l,v[1]/l,v[2]/l]; }\n"
    "function cross3(a,b) { return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]; }\n"
    "function sub3(a,b) { return [a[0]-b[0],a[1]-b[1],a[2]-b[2]]; }\n"
    "\n"
    "// ── Screenshot ───────────────────────────────────────────────────\n"
    "function rv3dShot(mult) {\n"
    "  if (!gl) return;\n"
    "  const ow=cnv.width, oh=cnv.height;\n"
    "  cnv.width=wrap.clientWidth*mult*Math.min(devicePixelRatio,2);\n"
    "  cnv.height=wrap.clientHeight*mult*Math.min(devicePixelRatio,2);\n"
    "  gl.viewport(0,0,cnv.width,cnv.height);\n"
    "  cnv.toBlob(blob => {\n"
    "    const a=document.createElement('a'); a.href=URL.createObjectURL(blob); a.download='rigart_'+Date.now()+'.png'; a.click(); URL.revokeObjectURL(a.href);\n"
    "    cnv.width=ow; cnv.height=oh; gl.viewport(0,0,ow,oh);\n"
    "    rv3dToast(mult>1?'PNG 4× exportado':'PNG exportado');\n"
    "  });\n"
    "}\n"
    "\n"
    "// ── Panel toggle ─────────────────────────────────────────────────\n"
    "window.rv3dTogglePanel = function() {\n"
    "  const body = document.getElementById('rv3d-panel-body');\n"
    "  const btn  = document.getElementById('rv3d-panel-toggle-btn');\n"
    "  if (!body) return;\n"
    "  body.classList.toggle('open');\n"
    "  if (btn) btn.textContent = body.classList.contains('open') ? '▴ CERRAR PANEL' : '▾ CONTROLES · MATERIAL · MESHES · ANIM · FX · INFO';\n"
    "};\n"
    "\n"
    "// ── Bind UI controls ─────────────────────────────────────────────\n"
    "function rv3dBind() {\n"
    "  // Tabs\n"
    "  document.querySelectorAll('.rv3d-ptab').forEach(tab => {\n"
    "    tab.addEventListener('click', () => {\n"
    "      document.querySelectorAll('.rv3d-ptab').forEach(t=>t.classList.remove('active'));\n"
    "      document.querySelectorAll('.rv3d-tab-content').forEach(c=>c.classList.remove('active'));\n"
    "      tab.classList.add('active');\n"
    "      const tgt = document.getElementById('rv3d-tab-'+tab.dataset.rv3dTab);\n"
    "      if (tgt) tgt.classList.add('active');\n"
    "    });\n"
    "  });\n"
    "\n"
    "  // Sliders helper\n"
    "  function bindS(id, valId, suf, cb) {\n"
    "    const sl = document.getElementById(id); const vl = document.getElementById(valId);\n"
    "    if (!sl) return;\n"
    "    sl.addEventListener('input', () => {\n"
    "      const v = parseFloat(sl.value);\n"
    "      if (vl) vl.textContent = v.toFixed(sl.step && sl.step.includes('.') ? sl.step.split('.')[1].length : 1) + (suf||'');\n"
    "      if (cb) cb(v);\n"
    "    });\n"
    "  }\n"
    "\n"
    "  bindS('rv3d-fov',    'rv3d-fov-v',    '°', v => fovDeg=v);\n"
    "  bindS('rv3d-expo',   'rv3d-expo-v',   '',  v => exposure=v);\n"
    "  bindS('rv3d-rotspd', 'rv3d-rotspd-v', '×', v => rotSpeed=v*0.003);\n"
    "  bindS('rv3d-amb',    'rv3d-amb-v',    '',  v => lights.amb.int=v);\n"
    "  bindS('rv3d-key',    'rv3d-key-v',    '',  v => lights.key.int=v);\n"
    "  bindS('rv3d-fill',   'rv3d-fill-v',   '',  v => lights.fill.int=v);\n"
    "  bindS('rv3d-rim',    'rv3d-rim-v',    '',  v => lights.rim.int=v);\n"
    "  bindS('rv3d-rough',  'rv3d-rough-v',  '',  v => matState.roughness=v);\n"
    "  bindS('rv3d-metal',  'rv3d-metal-v',  '',  v => matState.metalness=v);\n"
    "  bindS('rv3d-opacity','rv3d-opacity-v','',  v => matState.opacity=v);\n"
    "  bindS('rv3d-anim-spd','rv3d-anim-spd-v','×', () => {});\n"
    "\n"
    "  // Colors\n"
    "  const bgEl=document.getElementById('rv3d-bg-col'); if(bgEl) bgEl.addEventListener('input',e=>bgColor=hexToRGB(e.target.value));\n"
    "  const kcEl=document.getElementById('rv3d-key-col'); if(kcEl) kcEl.addEventListener('input',e=>lights.key.col=hexToRGB(e.target.value));\n"
    "  const rcEl=document.getElementById('rv3d-rim-col'); if(rcEl) rcEl.addEventListener('input',e=>lights.rim.col=hexToRGB(e.target.value));\n"
    "  const mcEl=document.getElementById('rv3d-mat-col'); if(mcEl) mcEl.addEventListener('input',e=>matState.color=hexToRGB(e.target.value));\n"
    "\n"
    "  // Toggles\n"
    "  const arEl=document.getElementById('rv3d-autorot'); if(arEl) arEl.addEventListener('change',e=>autoRotate=e.target.checked);\n"
    "  const grEl=document.getElementById('rv3d-grid');    if(grEl) grEl.addEventListener('change',e=>showGrid=e.target.checked);\n"
    "  const goEl=document.getElementById('rv3d-ground');  if(goEl) goEl.addEventListener('change',e=>showGround=e.target.checked);\n"
    "  const mmEl=document.getElementById('rv3d-mat-mode'); if(mmEl) mmEl.addEventListener('change',e=>matState.mode=e.target.value);\n"
    "  const fgEl=document.getElementById('rv3d-fog-toggle'); if(fgEl) fgEl.addEventListener('change',e=>{ fogEnabled=e.target.checked; });\n"
    "  const fdEl=document.getElementById('rv3d-fog-density'); if(fdEl) fdEl.addEventListener('input',e=>{ fogDensity=parseFloat(e.target.value); const vl=document.getElementById('rv3d-fog-density-v'); if(vl) vl.textContent=fogDensity.toFixed(3); });\n"
    "  const shEl=document.getElementById('rv3d-shadow'); if(shEl) shEl.addEventListener('change',e=>shadowEnabled=e.target.checked);\n"
    "\n"
    "  // Presets\n"
    "  const matPresets = {\n"
    "    gold:    [0.784,0.644,0.353, 0.9, 0.15],\n"
    "    chrome:  [0.690,0.769,0.847, 1.0, 0.05],\n"
    "    carbon:  [0.102,0.102,0.157, 0.4, 0.80],\n"
    "    plaster: [0.910,0.878,0.816, 0.0, 0.95],\n"
    "    jade:    [0.290,0.486,0.349, 0.0, 0.40],\n"
    "    ruby:    [0.545,0.102,0.102, 0.2, 0.30],\n"
    "    cobalt:  [0.102,0.227,0.361, 0.6, 0.20],\n"
    "    pearl:   [0.980,0.980,0.980, 0.0, 0.10],\n"
    "  };\n"
    "  document.querySelectorAll('.rv3d-swatch').forEach(sw => {\n"
    "    sw.addEventListener('click', () => {\n"
    "      document.querySelectorAll('.rv3d-swatch').forEach(s=>s.classList.remove('active'));\n"
    "      sw.classList.add('active');\n"
    "      const p=matPresets[sw.dataset.rv3dPreset]; if(!p) return;\n"
    "      matState.color=[p[0],p[1],p[2]]; matState.metalness=p[3]; matState.roughness=p[4];\n"
    "      matState.mode='override';\n"
    "      const mm=document.getElementById('rv3d-mat-mode'); if(mm) mm.value='override';\n"
    "      const mr=document.getElementById('rv3d-rough'); if(mr){mr.value=p[4]; document.getElementById('rv3d-rough-v').textContent=p[4].toFixed(2);}\n"
    "      const mt=document.getElementById('rv3d-metal'); if(mt){mt.value=p[3]; document.getElementById('rv3d-metal-v').textContent=p[3].toFixed(2);}\n"
    "    });\n"
    "  });\n"
    "\n"
    "  // Header buttons\n"
    "  const rcBtn=document.getElementById('rv3d-reset-cam'); if(rcBtn) rcBtn.addEventListener('click', () => {\n"
    "    sph.theta=0.5; sph.phi=1.25; sph.radius=sceneDiam*2.4;\n"
    "    target[0]=sceneCenter[0]; target[1]=sceneCenter[1]; target[2]=sceneCenter[2];\n"
    "    rv3dToast('Cámara centrada');\n"
    "  });\n"
    "  const arBtn=document.getElementById('rv3d-auto-rot'); if(arBtn) arBtn.addEventListener('click', () => {\n"
    "    autoRotate=!autoRotate;\n"
    "    arBtn.classList.toggle('rv3d-btn-accent', autoRotate);\n"
    "    arBtn.classList.toggle('rv3d-btn-ghost', !autoRotate);\n"
    "    const ae=document.getElementById('rv3d-autorot'); if(ae) ae.checked=autoRotate;\n"
    "  });\n"
    "  const wBtn=document.getElementById('rv3d-wire-btn'); if(wBtn) wBtn.addEventListener('click', () => {\n"
    "    wireMode=!wireMode;\n"
    "    wBtn.classList.toggle('rv3d-btn-accent', wireMode);\n"
    "    wBtn.classList.toggle('rv3d-btn-ghost', !wireMode);\n"
    "    rv3dToast(wireMode?'Wireframe ON':'Wireframe OFF');\n"
    "  });\n"
    "  const sBtn=document.getElementById('rv3d-shot-btn'); if(sBtn) sBtn.addEventListener('click', ()=>rv3dShot(1));\n"
    "\n"
    "  // Transport\n"
    "  const tPlay=document.getElementById('rv3d-t-play'); if(tPlay) tPlay.addEventListener('click', () => {\n"
    "    animPlaying=!animPlaying;\n"
    "    if(animPlaying && currentAnimDuration>0) {}\n"
    "    tPlay.classList.toggle('active', animPlaying);\n"
    "  });\n"
    "  const tLoop=document.getElementById('rv3d-t-loop'); if(tLoop) tLoop.addEventListener('click', () => {\n"
    "    animLooping=!animLooping; tLoop.classList.toggle('active', animLooping);\n"
    "  });\n"
    "\n"
    "  // Export\n"
    "  const ePng=document.getElementById('rv3d-exp-png'); if(ePng) ePng.addEventListener('click', ()=>rv3dShot(1));\n"
    "  const eHq=document.getElementById('rv3d-exp-hq');  if(eHq)  eHq.addEventListener('click', ()=>rv3dShot(4));\n"
    "  const eJs=document.getElementById('rv3d-exp-json'); if(eJs) eJs.addEventListener('click', () => {\n"
    "    const cfg={rigart:'v4.0',phi:PHI,exposure,fov:fovDeg,autoRotate,lights,matState};\n"
    "    const b=new Blob([JSON.stringify(cfg,null,2)],{type:'application/json'});\n"
    "    const a=document.createElement('a'); a.href=URL.createObjectURL(b); a.download='rigart_cfg.json'; a.click(); URL.revokeObjectURL(a.href);\n"
    "    rv3dToast('Config exportada');\n"
    "  });\n"
    "  const eSh=document.getElementById('rv3d-exp-share'); if(eSh) eSh.addEventListener('click', () => {\n"
    "    navigator.clipboard?.writeText(location.href).then(()=>rv3dToast('URL copiada'));\n"
    "  });\n"
    "\n"
    "  // File inputs\n"
    "  const fi1=document.getElementById('rv3d-file-input'); if(fi1) fi1.addEventListener('change',e=>{const f=e.target.files[0];if(f)rv3dLoadFile(f);});\n"
    "  const fi2=document.getElementById('rv3d-file-input2'); if(fi2) fi2.addEventListener('change',e=>{const f=e.target.files[0];if(f)rv3dLoadFile(f);});\n"
    "\n"
    "  // Drag & drop on canvas\n"
    "  if (wrap) {\n"
    "    wrap.addEventListener('dragover', e=>e.preventDefault());\n"
    "    wrap.addEventListener('drop', e=>{\n"
    "      e.preventDefault();\n"
    "      const f=e.dataTransfer.files[0];\n"
    "      if(f&&(f.name.endsWith('.glb')||f.name.endsWith('.gltf'))) rv3dLoadFile(f);\n"
    "      else rv3dToast('Solo GLB / GLTF');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  // Anim progress click\n"
    "  const apw=document.getElementById('rv3d-anim-prog-wrap'); if(apw) apw.addEventListener('click', e=>{\n"
    "    if(!currentAnimDuration) return;\n"
    "    const rect=apw.getBoundingClientRect();\n"
    "    animTime=(e.clientX-rect.left)/rect.width*currentAnimDuration;\n"
    "  });\n"
    "\n"
    "  // ── Generar HTML Soberano ─────────────────────────────────────\n"
    "  function rv3dBuildStandaloneHTML() {\n"
    "    const title    = document.getElementById('rv3d-gen-title')?.value || 'RIgArt · Escena Soberana';\n"
    "    const autoRot  = document.getElementById('rv3d-gen-autorot')?.checked ?? true;\n"
    "    const stats    = document.getElementById('rv3d-gen-stats')?.checked  ?? true;\n"
    "    const hdr      = document.getElementById('rv3d-gen-hdr')?.checked    ?? false;\n"
    "    const bg       = document.getElementById('rv3d-bg-col')?.value       || '#030208';\n"
    "    const rough    = document.getElementById('rv3d-rough')?.value        || '0.5';\n"
    "    const metal    = document.getElementById('rv3d-metal')?.value        || '0.0';\n"
    "    const fov      = document.getElementById('rv3d-fov')?.value          || '42';\n"
    "    const expo     = document.getElementById('rv3d-expo')?.value         || '1.1';\n"
    "\n"
    "    // Serialise current scene meshes as JS arrays (geometry only, no textures)\n"
    "    let meshDataJS = 'const RG_MESHES = [];\\n';\n"
    "    if (typeof meshes !== 'undefined' && meshes.length) {\n"
    "      meshDataJS = '/* Escena exportada desde RigCom v17 */\\n';\n"
    "      meshDataJS += `const RG_MESHES_META = ${JSON.stringify(meshes.map(m=>({\n"
    "        name: m.name, tris: m.tris,\n"
    "        color: m.color, metalness: m.metalness, roughness: m.roughness\n"
    "      })))};\\n`;\n"
    "    }\n"
    "\n"
    "    const PHI_VAL = 1.6180339887498948482;\n"
    "\n"
    "    \n"
    "function hexToRGBArr(hex) {\n"
    "    const h = hex.replace('#','');\n"
    "    return [parseInt(h.slice(0,2),16)/255, parseInt(h.slice(2,4),16)/255, parseInt(h.slice(4,6),16)/255].map(v=>v.toFixed(3)).join(',');\n"
    "  }\n"
    "\n"
    "  const html = `<!DOCTYPE html>\n"
    "<html lang=\"es\">\n"
    "<head>\n"
    "<meta charset=\"UTF-8\">\n"
    "<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,user-scalable=no,viewport-fit=cover\">\n"
    "${hdr ? '<meta name=\"color-gamut\" content=\"p3\">' : ''}\n"
    "<title>${title}</title>\n"
    "<style>\n"
    "*,*::before,*::after{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent}\n"
    "html,body{width:100%;height:100%;overflow:hidden;background:${bg};font-family:'JetBrains Mono',monospace}\n"
    "canvas{display:block;width:100%!important;height:100%!important;touch-action:none}\n"
    "#wrap{width:100%;height:100dvh;position:relative}\n"
    "#hud{position:absolute;top:14px;left:14px;pointer-events:none;${stats?'':'display:none'}}\n"
    ".hk{font-size:8px;letter-spacing:2px;color:rgba(200,164,90,.45);line-height:2.2}\n"
    ".hv{font-size:10px;letter-spacing:1px;color:rgba(200,164,90,.75)}\n"
    "#badge{position:absolute;top:14px;right:14px;font-size:8px;letter-spacing:2px;color:rgba(200,164,90,.35);${stats?'':'display:none'}}\n"
    "#phi-sig{position:absolute;bottom:14px;right:14px;font-size:7px;letter-spacing:2px;color:rgba(200,164,90,.2)}\n"
    ".corner{position:absolute;width:14px;height:14px;pointer-events:none}\n"
    ".tl{top:8px;left:8px;border-top:1px solid rgba(200,164,90,.18);border-left:1px solid rgba(200,164,90,.18)}\n"
    ".tr{top:8px;right:8px;border-top:1px solid rgba(200,164,90,.18);border-right:1px solid rgba(200,164,90,.18)}\n"
    ".bl{bottom:8px;left:8px;border-bottom:1px solid rgba(200,164,90,.18);border-left:1px solid rgba(200,164,90,.18)}\n"
    ".br{bottom:8px;right:8px;border-bottom:1px solid rgba(200,164,90,.18);border-right:1px solid rgba(200,164,90,.18)}\n"
    "</style>\n"
    "</head>\n"
    "<body>\n"
    "<div id=\"wrap\">\n"
    "  <div class=\"corner tl\"></div><div class=\"corner tr\"></div>\n"
    "  <div class=\"corner bl\"></div><div class=\"corner br\"></div>\n"
    "  <canvas id=\"c\"></canvas>\n"
    "  <div id=\"hud\">\n"
    "    <div class=\"hk\">MESHES <span class=\"hv\" id=\"h-m\">—</span></div>\n"
    "    <div class=\"hk\">TRIS   <span class=\"hv\" id=\"h-t\">—</span></div>\n"
    "    <div class=\"hk\">FPS    <span class=\"hv\" id=\"h-f\">—</span></div>\n"
    "  </div>\n"
    "  <div id=\"badge\">— fps</div>\n"
    "  <div id=\"phi-sig\">φ = ${PHI_VAL} · RIgArt Soberano</div>\n"
    "</div>\n"
    "<scr'+'ipt>\n"
    "'use strict';\n"
    "/* ══════════════════════════════════════════════════════════════════\n"
    "   RIgArt · ${title}\n"
    "   Motor WebGL2 Soberano · φ = ${PHI_VAL}\n"
    "   Generado por RigCom v17 · ${new Date().toISOString()}\n"
    "   Autor: Richard Felipe Urbina\n"
    "══════════════════════════════════════════════════════════════════ */\n"
    "${meshDataJS}\n"
    "const PHI = ${PHI_VAL};\n"
    "const BG  = [${hexToRGBArr(bg)}];\n"
    "\n"
    "// ── mat4 utils ──────────────────────────────────────────────────\n"
    "const mat4={\n"
    "  create(){ const m=new Float32Array(16);m[0]=m[5]=m[10]=m[15]=1;return m; },\n"
    "  perspective(o,f,a,n,fa){ const t=1/Math.tan(f/2),nf=1/(n-fa);\n"
    "    o[0]=t/a;o[1]=o[2]=o[3]=o[4]=0;o[5]=t;o[6]=o[7]=o[8]=o[9]=0;\n"
    "    o[10]=(fa+n)*nf;o[11]=-1;o[12]=o[13]=0;o[14]=2*fa*n*nf;o[15]=0;return o; },\n"
    "  identity(o){ o.fill(0);o[0]=o[5]=o[10]=o[15]=1;return o; },\n"
    "  multiply(o,a,b){ for(let i=0;i<4;i++)for(let j=0;j<4;j++){let s=0;for(let k=0;k<4;k++)s+=a[i*4+k]*b[k*4+j];o[i*4+j]=s;}return o; },\n"
    "  lookAt(o,e,c,u){\n"
    "    let fx=c[0]-e[0],fy=c[1]-e[1],fz=c[2]-e[2];\n"
    "    let l=Math.sqrt(fx*fx+fy*fy+fz*fz);if(!l)return mat4.identity(o);\n"
    "    fx/=l;fy/=l;fz/=l;\n"
    "    let sx=fy*u[2]-fz*u[1],sy=fz*u[0]-fx*u[2],sz=fx*u[1]-fy*u[0];\n"
    "    l=Math.sqrt(sx*sx+sy*sy+sz*sz);if(l){sx/=l;sy/=l;sz/=l;}\n"
    "    const ux=sy*fz-sz*fy,uy=sz*fx-sx*fz,uz=sx*fy-sy*fx;\n"
    "    o[0]=sx;o[1]=ux;o[2]=-fx;o[3]=0;o[4]=sy;o[5]=uy;o[6]=-fy;o[7]=0;\n"
    "    o[8]=sz;o[9]=uz;o[10]=-fz;o[11]=0;\n"
    "    o[12]=-(sx*e[0]+sy*e[1]+sz*e[2]);o[13]=-(ux*e[0]+uy*e[1]+uz*e[2]);\n"
    "    o[14]=fx*e[0]+fy*e[1]+fz*e[2];o[15]=1;return o; }\n"
    "};\n"
    "\n"
    "// ── Shaders ─────────────────────────────────────────────────────\n"
    "const VS=\\`#version 300 es\n"
    "precision highp float;\n"
    "layout(location=0) in vec3 aP;\n"
    "layout(location=1) in vec3 aN;\n"
    "layout(location=2) in vec2 aUV;\n"
    "uniform mat4 uMVP,uMod;\n"
    "out vec3 vP,vN; out vec2 vUV;\n"
    "void main(){ vec4 wp=uMod*vec4(aP,1.); vP=wp.xyz; vN=normalize((uMod*vec4(aN,0.)).xyz); vUV=aUV; gl_Position=uMVP*wp; }\\`;\n"
    "\n"
    "const FS=\\`#version 300 es\n"
    "precision highp float;\n"
    "in vec3 vP,vN; in vec2 vUV;\n"
    "uniform vec3 uCam,uAlb; uniform float uR,uM,uExp,uAmb;\n"
    "out vec4 col;\n"
    "const float PI=3.14159265;\n"
    "float D(float h,float r){float a=r*r,a2=a*a,d=h*h*(a2-1.)+1.;return a2/(PI*d*d+1e-7);}\n"
    "float G(float nv,float nl,float r){float k=(r+1.)*(r+1.)/8.;float g1=nv/(nv*(1.-k)+k);float g2=nl/(nl*(1.-k)+k);return g1*g2;}\n"
    "vec3 F(float c,vec3 f0){return f0+(1.-f0)*pow(clamp(1.-c,0.,1.),5.);}\n"
    "vec3 CT(vec3 N,vec3 V,vec3 L,vec3 lc,float li){\n"
    "  vec3 H=normalize(V+L);float nl=max(dot(N,L),0.),nv=max(dot(N,V),.001),nh=max(dot(N,H),0.),vh=max(dot(V,H),0.);\n"
    "  vec3 f0=mix(vec3(.04),uAlb,uM);float d=D(nh,uR),g=G(nv,nl,uR);vec3 f=F(vh,f0);\n"
    "  vec3 sp=d*g*f/(4.*nv*nl+1e-7);vec3 kd=(1.-f)*(1.-uM);\n"
    "  return (kd*uAlb/PI+sp)*lc*li*nl;}\n"
    "vec3 aces(vec3 x){float a=2.51,b=.03,c=2.43,d=.59,e=.14;return clamp((x*(a*x+b))/(x*(c*x+d)+e),0.,1.);}\n"
    "void main(){\n"
    "  vec3 N=normalize(vN),V=normalize(uCam-vP);\n"
    "  vec3 c3=uAmb*uAlb*vec3(.08,.07,.1);\n"
    "  c3+=CT(N,V,normalize(vec3(-4.,-8.,-5.)),vec3(1.,.98,.94),1.2);\n"
    "  c3+=CT(N,V,normalize(vec3(5.,-2.,3.)),vec3(.53,.6,.8),.4);\n"
    "  c3+=CT(N,V,normalize(vec3(0.,3.,6.)),vec3(.79,.66,.3),.3);\n"
    "  c3*=uExp; c3=aces(c3); c3=pow(c3,vec3(1./2.2));\n"
    "  col=vec4(c3,1.); }\\`;\n"
    "\n"
    "// ── GL setup ────────────────────────────────────────────────────\n"
    "const cnv=document.getElementById('c');\n"
    "const wrap=document.getElementById('wrap');\n"
    "const gl=cnv.getContext('webgl2',{antialias:true,alpha:false,preserveDrawingBuffer:true,powerPreference:'high-performance'});\n"
    "if(!gl){ wrap.innerHTML='<p style=\"color:#c8a45a;text-align:center;padding:40px;font-size:10px;letter-spacing:2px\">WebGL2 no disponible</p>'; }\n"
    "\n"
    "function mkS(t,s){ const sh=gl.createShader(t);gl.shaderSource(sh,s);gl.compileShader(sh);return sh; }\n"
    "function mkP(vs,fs){ const p=gl.createProgram();gl.attachShader(p,mkS(gl.VERTEX_SHADER,vs));gl.attachShader(p,mkS(gl.FRAGMENT_SHADER,fs));gl.linkProgram(p);return p; }\n"
    "const prog=gl&&mkP(VS,FS);\n"
    "\n"
    "// ── Demo geometry (torus φ) ──────────────────────────────────────\n"
    "function genTorus(R,r,ts,rs){\n"
    "  const pos=[],nor=[],uvs=[],idx=[];\n"
    "  for(let i=0;i<=ts;i++){\n"
    "    const u=i/ts*Math.PI*2;\n"
    "    for(let j=0;j<=rs;j++){\n"
    "      const v=j/rs*Math.PI*2;\n"
    "      const cx=R+r*Math.cos(v),cy=r*Math.sin(v);\n"
    "      pos.push(cx*Math.cos(u),cy,cx*Math.sin(u));\n"
    "      const nx=Math.cos(v)*Math.cos(u),ny=Math.sin(v),nz=Math.cos(v)*Math.sin(u);\n"
    "      nor.push(nx,ny,nz); uvs.push(i/ts,j/rs);\n"
    "    }\n"
    "    if(i<ts){\n"
    "      const a=i*(rs+1),b=(i+1)*(rs+1);\n"
    "      for(let j=0;j<rs;j++){idx.push(a+j,b+j,b+j+1,a+j,b+j+1,a+j+1);}\n"
    "    }\n"
    "  }\n"
    "  return {pos,nor,uvs,idx};\n"
    "}\n"
    "\n"
    "let glMeshes=[];\n"
    "function uploadGeo(geo){\n"
    "  const vc=geo.pos.length/3;\n"
    "  const buf=new Float32Array(vc*8);\n"
    "  for(let i=0;i<vc;i++){buf[i*8]=geo.pos[i*3];buf[i*8+1]=geo.pos[i*3+1];buf[i*8+2]=geo.pos[i*3+2];buf[i*8+3]=geo.nor[i*3];buf[i*8+4]=geo.nor[i*3+1];buf[i*8+5]=geo.nor[i*3+2];buf[i*8+6]=geo.uvs[i*2];buf[i*8+7]=geo.uvs[i*2+1];}\n"
    "  const vb=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,vb);gl.bufferData(gl.ARRAY_BUFFER,buf,gl.STATIC_DRAW);\n"
    "  const ib=gl.createBuffer();const i32=new Uint32Array(geo.idx);gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,ib);gl.bufferData(gl.ELEMENT_ARRAY_BUFFER,i32,gl.STATIC_DRAW);\n"
    "  return {vb,ib,ic:geo.idx.length,vc};\n"
    "}\n"
    "\n"
    "if(gl){\n"
    "  // Demo: 3 geometrías φ\n"
    "  const t1=uploadGeo(genTorus(PHI,.35,64,32));\n"
    "  t1.col=[0.784,0.644,0.353];t1.met=0.9;t1.rou=0.15;t1.pos=[0,0,0];\n"
    "  glMeshes.push(t1);\n"
    "}\n"
    "\n"
    "// ── Camera ────────────────────────────────────────────────────────\n"
    "const sph={th:0.5,ph:1.25,r:4};const tgt=[0,0,0];\n"
    "let ar=${autoRot},rs=0.003,fovD=${fov},exp=${expo};\n"
    "function cam(){ return [tgt[0]+sph.r*Math.sin(sph.ph)*Math.sin(sph.th),tgt[1]+sph.r*Math.cos(sph.ph),tgt[2]+sph.r*Math.sin(sph.ph)*Math.cos(sph.th)]; }\n"
    "\n"
    "function resize(){ const w=wrap.clientWidth,h=wrap.clientHeight;cnv.width=w*Math.min(devicePixelRatio,2.5);cnv.height=h*Math.min(devicePixelRatio,2.5);gl&&gl.viewport(0,0,cnv.width,cnv.height); }\n"
    "window.addEventListener('resize',resize);resize();\n"
    "\n"
    "// ── Touch / mouse ────────────────────────────────────────────────\n"
    "let md=false,mb=-1,lm={},touches={},lpd=null,lpm=null;\n"
    "function sub3(a,b){return[a[0]-b[0],a[1]-b[1],a[2]-b[2]];}\n"
    "function cross3(a,b){return[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];}\n"
    "function norm3(v){const l=Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2])||1;return[v[0]/l,v[1]/l,v[2]/l];}\n"
    "cnv.addEventListener('touchstart',e=>{e.preventDefault();ar=false;Array.from(e.touches).forEach(t=>touches[t.identifier]={x:t.clientX,y:t.clientY});if(e.touches.length===2){lpd=Math.hypot(e.touches[0].clientX-e.touches[1].clientX,e.touches[0].clientY-e.touches[1].clientY);lpm={(x:(e.touches[0].clientX+e.touches[1].clientX)/2,y:(e.touches[0].clientY+e.touches[1].clientY)/2)};}},{passive:false});\n"
    "cnv.addEventListener('touchend',e=>{e.preventDefault();Array.from(e.changedTouches).forEach(t=>delete touches[t.identifier]);if(e.touches.length<2){lpd=null;lpm=null;}},{passive:false});\n"
    "cnv.addEventListener('touchmove',e=>{e.preventDefault();const ts=Array.from(e.touches);if(ts.length===1){const p=touches[ts[0].identifier];if(p){sph.th-=(ts[0].clientX-p.x)*.011;sph.ph=Math.max(.08,Math.min(Math.PI-.08,sph.ph+(ts[0].clientY-p.y)*.011));}touches[ts[0].identifier]={x:ts[0].clientX,y:ts[0].clientY};}else if(ts.length===2){const d=Math.hypot(ts[0].clientX-ts[1].clientX,ts[0].clientY-ts[1].clientY),m={(x:(ts[0].clientX+ts[1].clientX)/2,y:(ts[0].clientY+ts[1].clientY)/2)};if(lpd!=null){sph.r=Math.max(.05,Math.min(500,sph.r*(lpd/d)));if(lpm){const c=cam();const ri=norm3(cross3([0,1,0],norm3(sub3(c,tgt))));tgt[0]-=ri[0]*(m.x-lpm.x)*.002*sph.r;tgt[1]+=(m.y-lpm.y)*.002*sph.r;tgt[2]-=ri[2]*(m.x-lpm.x)*.002*sph.r;}}lpd=d;lpm=m;ts.forEach(t=>touches[t.identifier]={x:t.clientX,y:t.clientY});}},{passive:false});\n"
    "cnv.addEventListener('mousedown',e=>{md=true;mb=e.button;lm={x:e.clientX,y:e.clientY};ar=false;e.preventDefault();});\n"
    "window.addEventListener('mouseup',()=>md=false);\n"
    "window.addEventListener('mousemove',e=>{if(!md)return;const dx=e.clientX-lm.x,dy=e.clientY-lm.y;if(mb===0){sph.th-=dx*.01;sph.ph=Math.max(.08,Math.min(Math.PI-.08,sph.ph+dy*.01));}else if(mb===2){const c=cam();const ri=norm3(cross3([0,1,0],norm3(sub3(c,tgt))));tgt[0]-=ri[0]*dx*.002*sph.r;tgt[1]+=dy*.002*sph.r;tgt[2]-=ri[2]*dx*.002*sph.r;}lm={x:e.clientX,y:e.clientY};});\n"
    "cnv.addEventListener('wheel',e=>{sph.r=Math.max(.05,sph.r*(1+e.deltaY*.001));},{passive:true});\n"
    "cnv.addEventListener('contextmenu',e=>e.preventDefault());\n"
    "\n"
    "// ── Render loop ───────────────────────────────────────────────────\n"
    "let lt=0,ff=0,fl=performance.now();\n"
    "(function frame(ts){\n"
    "  requestAnimationFrame(frame);\n"
    "  const dt=Math.min((ts-lt)/1000,.05);lt=ts;\n"
    "  if(ar)sph.th+=rs*dt*60*.05;\n"
    "  if(!gl)return;\n"
    "  const w=cnv.width,h=cnv.height;\n"
    "  gl.clearColor(BG[0],BG[1],BG[2],1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);\n"
    "  gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);\n"
    "  const cp=cam();\n"
    "  const proj=mat4.perspective(mat4.create(),fovD*Math.PI/180,w/h,.001,1000);\n"
    "  const view=mat4.lookAt(mat4.create(),cp,tgt,[0,1,0]);\n"
    "  const vp=mat4.multiply(mat4.create(),proj,view);\n"
    "  gl.useProgram(prog);\n"
    "  for(const m of glMeshes){\n"
    "    const mod=mat4.identity(mat4.create());\n"
    "    if(m.pos){mod[12]=m.pos[0];mod[13]=m.pos[1];mod[14]=m.pos[2];}\n"
    "    const mvp=mat4.multiply(mat4.create(),vp,mod);\n"
    "    gl.uniformMatrix4fv(gl.getUniformLocation(prog,'uMVP'),false,mvp);\n"
    "    gl.uniformMatrix4fv(gl.getUniformLocation(prog,'uMod'),false,mod);\n"
    "    gl.uniform3fv(gl.getUniformLocation(prog,'uCam'),cp);\n"
    "    gl.uniform3fv(gl.getUniformLocation(prog,'uAlb'),m.col||[.784,.644,.353]);\n"
    "    gl.uniform1f(gl.getUniformLocation(prog,'uR'),m.rou??${rough});\n"
    "    gl.uniform1f(gl.getUniformLocation(prog,'uM'),m.met??${metal});\n"
    "    gl.uniform1f(gl.getUniformLocation(prog,'uExp'),exp);\n"
    "    gl.uniform1f(gl.getUniformLocation(prog,'uAmb'),.5);\n"
    "    gl.bindBuffer(gl.ARRAY_BUFFER,m.vb);\n"
    "    gl.enableVertexAttribArray(0);gl.vertexAttribPointer(0,3,gl.FLOAT,false,32,0);\n"
    "    gl.enableVertexAttribArray(1);gl.vertexAttribPointer(1,3,gl.FLOAT,false,32,12);\n"
    "    gl.enableVertexAttribArray(2);gl.vertexAttribPointer(2,2,gl.FLOAT,false,32,24);\n"
    "    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER,m.ib);\n"
    "    gl.drawElements(gl.TRIANGLES,m.ic,gl.UNSIGNED_INT,0);\n"
    "  }\n"
    "  ff++;const now=performance.now();\n"
    "  if(now-fl>=1000){const fps=Math.round(ff*1000/(now-fl));ff=0;fl=now;\n"
    "    const hf=document.getElementById('h-f');if(hf)hf.textContent=fps;\n"
    "    const ba=document.getElementById('badge');if(ba)ba.textContent=fps+' fps';}\n"
    "})();\n"
    "<\\/script>\n"
    "</body>\n"
    "</html>`;\n"
    "    return html;\n"
    "  }\n"
    "\n"
    "  function showGenResult(html) {\n"
    "    const res  = document.getElementById('rv3d-gen-result');\n"
    "    const pre  = document.getElementById('rv3d-html-preview');\n"
    "    const size = document.getElementById('rv3d-html-size');\n"
    "    const kb   = (html.length / 1024).toFixed(1);\n"
    "    const lines= html.split('\\n').length;\n"
    "    if (res)  res.style.display  = 'block';\n"
    "    if (pre)  pre.value          = html;\n"
    "    if (size) size.textContent   = `${kb} KB · ${lines} líneas · ${new Date().toLocaleTimeString('es',{hour12:false})}`;\n"
    "    // Scroll to result\n"
    "    res?.scrollIntoView({ behavior:'smooth', block:'nearest' });\n"
    "    // Wire download\n"
    "    const dl = document.getElementById('rv3d-html-dl');\n"
    "    if (dl) {\n"
    "      dl.onclick = () => {\n"
    "        const blob = new Blob([html], { type:'text/html' });\n"
    "        const a    = document.createElement('a');\n"
    "        a.href     = URL.createObjectURL(blob);\n"
    "        a.download = 'rigart_escena_soberana_' + Date.now() + '.html';\n"
    "        a.click();\n"
    "        URL.revokeObjectURL(a.href);\n"
    "        rv3dToast('HTML descargado ✓');\n"
    "      };\n"
    "    }\n"
    "    // Wire copy\n"
    "    const cp = document.getElementById('rv3d-html-copy');\n"
    "    if (cp) {\n"
    "      cp.onclick = () => {\n"
    "        navigator.clipboard?.writeText(html)\n"
    "          .then(() => rv3dToast('HTML copiado al clipboard ✓'))\n"
    "          .catch(() => {\n"
    "            // Fallback: select textarea\n"
    "            const ta = document.getElementById('rv3d-html-preview');\n"
    "            if (ta) { ta.select(); document.execCommand('copy'); rv3dToast('HTML copiado ✓'); }\n"
    "          });\n"
    "      };\n"
    "    }\n"
    "  }\n"
    "\n"
    "  // Botón LOCAL — genera en el navegador directamente\n"
    "  const genLocal = document.getElementById('rv3d-gen-local');\n"
    "  if (genLocal) {\n"
    "    genLocal.addEventListener('click', () => {\n"
    "      try {\n"
    "        const html = rv3dBuildStandaloneHTML();\n"
    "        showGenResult(html);\n"
    "        rv3dToast('HTML generado · ' + (html.length/1024).toFixed(1) + ' KB');\n"
    "      } catch(e) {\n"
    "        rv3dToast('Error: ' + e.message);\n"
    "        console.error(e);\n"
    "      }\n"
    "    });\n"
    "  }\n"
    "\n"
    "  // Botón SERVIDOR — manda WS cmd rigart_render → recibe HTML del backend C\n"
    "  const genWS = document.getElementById('rv3d-gen-ws');\n"
    "  if (genWS) {\n"
    "    genWS.addEventListener('click', () => {\n"
    "      if (typeof ws === 'undefined' || !ws || ws.readyState !== WebSocket.OPEN) {\n"
    "        rv3dToast('WS no conectado — usa LOCAL');\n"
    "        return;\n"
    "      }\n"
    "      const title   = document.getElementById('rv3d-gen-title')?.value  || 'RIgArt · Escena Soberana';\n"
    "      const autoRot = document.getElementById('rv3d-gen-autorot')?.checked ?? true;\n"
    "      const stats   = document.getElementById('rv3d-gen-stats')?.checked  ?? true;\n"
    "      const hdr     = document.getElementById('rv3d-gen-hdr')?.checked    ?? false;\n"
    "      const rough   = parseFloat(document.getElementById('rv3d-rough')?.value ?? 0.5);\n"
    "      const metal   = parseFloat(document.getElementById('rv3d-metal')?.value ?? 0.0);\n"
    "      const bg      = document.getElementById('rv3d-bg-col')?.value || '#030208';\n"
    "      ws.send(JSON.stringify({\n"
    "        cmd:'rigart_render',\n"
    "        title, auto_rotate: autoRot, show_stats: stats, hdr_p3: hdr,\n"
    "        roughness: rough, metallic: metal, bg_color: bg,\n"
    "        light_dir: [4.0, 8.0, 5.0],\n"
    "        light_color: [1.0, 0.98, 0.94],\n"
    "        tex_scale: 1.0\n"
    "      }));\n"
    "      rv3dToast('Enviando a servidor…');\n"
    "    });\n"
    "  }\n"
    "\n"
    "  // Receptor WS: cuando llega ev \"rigart_render_result\" → mostrar HTML\n"
    "  if (typeof window._rv3dWSHookInstalled === 'undefined') {\n"
    "    window._rv3dWSHookInstalled = true;\n"
    "    const origOnMsg = typeof onWsMessage === 'function' ? onWsMessage : null;\n"
    "    window._rv3dHookWsMessage = function(data) {\n"
    "      try {\n"
    "        const msg = JSON.parse(data);\n"
    "        if (msg.ev === 'rigart_render_result') {\n"
    "          if (msg.html) {\n"
    "            showGenResult(msg.html);\n"
    "            rv3dToast('HTML recibido del servidor · ' + (msg.html.length/1024).toFixed(1) + ' KB');\n"
    "          } else if (msg.error) {\n"
    "            rv3dToast('Error servidor: ' + msg.error);\n"
    "          }\n"
    "          return true; // consumed\n"
    "        }\n"
    "      } catch(e) {}\n"
    "      return false;\n"
    "    };\n"
    "  }\n"
    "}\n"
    "\n"
    "if (gl) rv3dBind();\n"
    "\n"
    "// ── KEYBOARD SHORTCUTS for 3D Visor ──────────────────────────\n"
    "document.addEventListener('keydown', e => {\n"
    "  const active = document.getElementById('panel-rigart');\n"
    "  if (!active || !active.classList.contains('on')) return;\n"
    "  const tag = e.target.tagName;\n"
    "  if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;\n"
    "  switch(e.key.toLowerCase()) {\n"
    "    case 'f': rv3dSetView('front'); break;\n"
    "    case 'b': rv3dSetView('back');  break;\n"
    "    case 't': rv3dSetView('top');   break;\n"
    "    case 'r': { const rcBtn=document.getElementById('rv3d-reset-cam'); if(rcBtn) rcBtn.click(); } break;\n"
    "    case 'a': { const ae=document.getElementById('rv3d-autorot'); if(ae) { ae.checked=!ae.checked; autoRotate=ae.checked; rv3dToast('Auto-rot '+( autoRotate?'ON':'OFF')); } } break;\n"
    "    case 'w': { const wb=document.getElementById('rv3d-wire-btn'); if(wb) wb.click(); } break;\n"
    "    case 'g': window.rv3dToggleGeoMenu(); break;\n"
    "    case 'm': { const mb=document.getElementById('rv3d-measure-btn'); if(mb) mb.click(); } break;\n"
    "    case 'e': { const eb=document.getElementById('rv3d-env-btn'); if(eb) eb.click(); } break;\n"
    "    case 'x': window.rv3dToggleFullscreen(); break;\n"
    "    case 'i': rv3dSetView('iso'); break;\n"
    "    case 'l': rv3dSetView('left'); break;\n"
    "    case 'z': rv3dSetView('right'); break;\n"
    "  }\n"
    "});\n"
    "\n"
    "// ══════════════════════════════════════════════════════════════\n"
    "//  PRIMITIVAS PROCEDURALES — WebGL2 soberano · φ = 1.618\n"
    "//  Dodecaedro · Icósfera · Cilindro · Cono · Esfera · Cubo · Toro · Plano\n"
    "//  Layout interleaved: pos(3)+norm(3)+uv(2) = 8 floats = 32 bytes\n"
    "// ══════════════════════════════════════════════════════════════\n"
    "(function(){\n"
    "'use strict';\n"
    "\n"
    "// ── Util: build a GPU mesh from flat arrays ──────────────────\n"
    "function uploadMesh(positions, normals, uvs, indices) {\n"
    "  if (!gl) return null;\n"
    "  const vc = positions.length / 3;\n"
    "  const data = new Float32Array(vc * 8);\n"
    "  for (let i = 0; i < vc; i++) {\n"
    "    data[i*8+0] = positions[i*3+0];\n"
    "    data[i*8+1] = positions[i*3+1];\n"
    "    data[i*8+2] = positions[i*3+2];\n"
    "    data[i*8+3] = normals ? normals[i*3+0] : 0;\n"
    "    data[i*8+4] = normals ? normals[i*3+1] : 1;\n"
    "    data[i*8+5] = normals ? normals[i*3+2] : 0;\n"
    "    data[i*8+6] = uvs ? uvs[i*2+0] : 0;\n"
    "    data[i*8+7] = uvs ? uvs[i*2+1] : 0;\n"
    "  }\n"
    "  const vbuf = gl.createBuffer();\n"
    "  gl.bindBuffer(gl.ARRAY_BUFFER, vbuf);\n"
    "  gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW);\n"
    "  let ibuf = null, indexCount = 0;\n"
    "  if (indices && indices.length) {\n"
    "    const idx32 = new Uint32Array(indices.length);\n"
    "    for (let i = 0; i < indices.length; i++) idx32[i] = indices[i];\n"
    "    ibuf = gl.createBuffer();\n"
    "    gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, ibuf);\n"
    "    gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, idx32, gl.STATIC_DRAW);\n"
    "    indexCount = indices.length;\n"
    "  }\n"
    "  return { vbuf, ibuf, indexCount, vertCount: vc };\n"
    "}\n"
    "\n"
    "function normalize3v(v) {\n"
    "  const l = Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]) || 1;\n"
    "  return [v[0]/l, v[1]/l, v[2]/l];\n"
    "}\n"
    "\n"
    "// ── ESFERA UV ────────────────────────────────────────────────\n"
    "function genSphere(r=1, stacks=32, slices=32) {\n"
    "  const pos=[], nor=[], uvs=[], idx=[];\n"
    "  for (let i=0;i<=stacks;i++) {\n"
    "    const phi = Math.PI * i / stacks;\n"
    "    const sp=Math.sin(phi), cp=Math.cos(phi);\n"
    "    for (let j=0;j<=slices;j++) {\n"
    "      const theta = 2*Math.PI*j/slices;\n"
    "      const st=Math.sin(theta), ct=Math.cos(theta);\n"
    "      const x=r*sp*ct, y=r*cp, z=r*sp*st;\n"
    "      pos.push(x,y,z); nor.push(x/r,y/r,z/r); uvs.push(j/slices, i/stacks);\n"
    "    }\n"
    "  }\n"
    "  for (let i=0;i<stacks;i++) for (let j=0;j<slices;j++) {\n"
    "    const a=i*(slices+1)+j, b=a+slices+1;\n"
    "    idx.push(a,b,a+1, b,b+1,a+1);\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── ICÓSFERA (subdivisión de icosaedro) ──────────────────────\n"
    "function genIcosphere(r=1, subdivisions=3) {\n"
    "  const PHI = 1.6180339887498948482;\n"
    "  // 12 vértices del icosaedro\n"
    "  const t = Math.sqrt(PHI*PHI+1);\n"
    "  const raw = [\n"
    "    [-1, PHI,0],[1,PHI,0],[-1,-PHI,0],[1,-PHI,0],\n"
    "    [0,-1,PHI],[0,1,PHI],[0,-1,-PHI],[0,1,-PHI],\n"
    "    [PHI,0,-1],[PHI,0,1],[-PHI,0,-1],[-PHI,0,1]\n"
    "  ].map(v => { const l=Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]); return [v[0]/l,v[1]/l,v[2]/l]; });\n"
    "\n"
    "  let faces = [\n"
    "    [0,11,5],[0,5,1],[0,1,7],[0,7,10],[0,10,11],\n"
    "    [1,5,9],[5,11,4],[11,10,2],[10,7,6],[7,1,8],\n"
    "    [3,9,4],[3,4,2],[3,2,6],[3,6,8],[3,8,9],\n"
    "    [4,9,5],[2,4,11],[6,2,10],[8,6,7],[9,8,1]\n"
    "  ];\n"
    "\n"
    "  const midCache = new Map();\n"
    "  function midpoint(verts, a, b) {\n"
    "    const key = a < b ? `${a}_${b}` : `${b}_${a}`;\n"
    "    if (midCache.has(key)) return midCache.get(key);\n"
    "    const va=verts[a], vb=verts[b];\n"
    "    const v = normalize3v([(va[0]+vb[0])*.5,(va[1]+vb[1])*.5,(va[2]+vb[2])*.5]);\n"
    "    verts.push(v); const idx=verts.length-1;\n"
    "    midCache.set(key,idx); return idx;\n"
    "  }\n"
    "\n"
    "  let verts = raw.slice();\n"
    "  for (let s=0;s<subdivisions;s++) {\n"
    "    const next=[];\n"
    "    for (const [a,b,c] of faces) {\n"
    "      const ab=midpoint(verts,a,b), bc=midpoint(verts,b,c), ca=midpoint(verts,c,a);\n"
    "      next.push([a,ab,ca],[ab,b,bc],[ca,bc,c],[ab,bc,ca]);\n"
    "    }\n"
    "    faces=next;\n"
    "  }\n"
    "\n"
    "  const pos=[], nor=[], uvs=[], idx=[];\n"
    "  verts.forEach(v => {\n"
    "    const n=normalize3v(v);\n"
    "    pos.push(n[0]*r,n[1]*r,n[2]*r);\n"
    "    nor.push(n[0],n[1],n[2]);\n"
    "    const u=0.5+Math.atan2(n[2],n[0])/(2*Math.PI);\n"
    "    const vv=0.5-Math.asin(Math.max(-1,Math.min(1,n[1])))/Math.PI;\n"
    "    uvs.push(u,vv);\n"
    "  });\n"
    "  faces.forEach(([a,b,c])=>idx.push(a,b,c));\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── DODECAEDRO ───────────────────────────────────────────────\n"
    "function genDodecahedron(r=1) {\n"
    "  const PHI = 1.6180339887498948482;\n"
    "  const s = 1/Math.sqrt(3);\n"
    "  const vs = 1/PHI/Math.sqrt(3);\n"
    "  const vp = PHI/Math.sqrt(3);\n"
    "  // 20 vértices\n"
    "  const rawV = [\n"
    "    [s,s,s],[s,s,-s],[s,-s,s],[s,-s,-s],\n"
    "    [-s,s,s],[-s,s,-s],[-s,-s,s],[-s,-s,-s],\n"
    "    [0,vs,vp],[0,vs,-vp],[0,-vs,vp],[0,-vs,-vp],\n"
    "    [vs,vp,0],[vs,-vp,0],[-vs,vp,0],[-vs,-vp,0],\n"
    "    [vp,0,vs],[vp,0,-vs],[-vp,0,vs],[-vp,0,-vs]\n"
    "  ];\n"
    "  // 12 pentágonos (cada uno se tesela en 3 triángulos)\n"
    "  const rawF = [\n"
    "    [0,8,4,14,12],[0,12,1,9,2],[1,12,14,5,9],\n"
    "    [2,9,5,7,3],[3,7,19,11,17],[3,17,16,0,2],\n"
    "    [4,10,6,18,8],[5,14,4,8,18],[5,18,6,15,19],\n"
    "    [6,15,13,2,10],[10,2,16,13,6],[11,7,5,19,15],\n"
    "    // (note: standard dodecahedron has 12 faces)\n"
    "    [0,16,17,1,12],[1,17,3,11,9],[9,11,15,6,5],\n"
    "    [8,18,19,7,14],[13,15,11,3,2],[7,5,9,11,15],\n"
    "    [16,0,8,18,13],[17,3,7,19,13]\n"
    "  ];\n"
    "  // Use the proper 12 pentagonal faces\n"
    "  const faces12 = [\n"
    "    [0,8,4,14,12],[2,9,5,14,0],[0,12,1,17,16],\n"
    "    [1,9,5,19,3],[3,11,7,19,5],[2,16,13,6,10],\n"
    "    [4,8,18,6,10],[8,0,16,13,18],[18,13,15,6,10],\n"
    "    [6,15,11,3,2],[12,14,5,9,1],[7,11,15,13,19]\n"
    "  ];\n"
    "\n"
    "  const pos=[], nor=[], uvs=[], idx=[];\n"
    "  let vi=0;\n"
    "  for (const face of faces12) {\n"
    "    // Face center\n"
    "    let cx=0,cy=0,cz=0;\n"
    "    face.forEach(fi=>{cx+=rawV[fi][0];cy+=rawV[fi][1];cz+=rawV[fi][2];});\n"
    "    cx/=face.length; cy/=face.length; cz/=face.length;\n"
    "    const cn=normalize3v([cx,cy,cz]);\n"
    "    const base=vi;\n"
    "    // Pentagon vertices\n"
    "    face.forEach((fi,i)=>{\n"
    "      const v=normalize3v(rawV[fi]);\n"
    "      pos.push(v[0]*r,v[1]*r,v[2]*r);\n"
    "      nor.push(cn[0],cn[1],cn[2]);\n"
    "      uvs.push(i/face.length,0);\n"
    "      vi++;\n"
    "    });\n"
    "    // Fan triangulation\n"
    "    for(let i=1;i<face.length-1;i++){\n"
    "      idx.push(base,base+i,base+i+1);\n"
    "    }\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── CUBO ─────────────────────────────────────────────────────\n"
    "function genCube(s=1) {\n"
    "  const h=s*.5;\n"
    "  const faces=[\n"
    "    {n:[0,0,1], verts:[[h,h,h],[-h,h,h],[-h,-h,h],[h,-h,h]]},\n"
    "    {n:[0,0,-1],verts:[[-h,h,-h],[h,h,-h],[h,-h,-h],[-h,-h,-h]]},\n"
    "    {n:[0,1,0], verts:[[h,h,-h],[-h,h,-h],[-h,h,h],[h,h,h]]},\n"
    "    {n:[0,-1,0],verts:[[h,-h,h],[-h,-h,h],[-h,-h,-h],[h,-h,-h]]},\n"
    "    {n:[1,0,0], verts:[[h,h,-h],[h,h,h],[h,-h,h],[h,-h,-h]]},\n"
    "    {n:[-1,0,0],verts:[[-h,h,h],[-h,h,-h],[-h,-h,-h],[-h,-h,h]]}\n"
    "  ];\n"
    "  const pos=[],nor=[],uvs=[],idx=[];\n"
    "  let vi=0;\n"
    "  for(const {n,verts} of faces){\n"
    "    verts.forEach(([x,y,z],i)=>{\n"
    "      pos.push(x,y,z); nor.push(...n);\n"
    "      uvs.push(i===0||i===3?1:0, i<2?1:0);\n"
    "    });\n"
    "    idx.push(vi,vi+1,vi+2, vi,vi+2,vi+3);\n"
    "    vi+=4;\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── CILINDRO ────────────────────────────────────────────────\n"
    "function genCylinder(rTop=0.5, rBot=0.5, h=2, segs=32) {\n"
    "  const pos=[],nor=[],uvs=[],idx=[];\n"
    "  const half=h*.5;\n"
    "  // Side\n"
    "  for(let i=0;i<=segs;i++){\n"
    "    const theta=2*Math.PI*i/segs;\n"
    "    const st=Math.sin(theta),ct=Math.cos(theta);\n"
    "    const slope=normalize3v([rBot-rTop,h,0]); // for normals on tapered\n"
    "    const nx=ct, nz=st;\n"
    "    for(const [y,r] of [[half,rTop],[-half,rBot]]){\n"
    "      pos.push(r*ct,y,r*st);\n"
    "      nor.push(nx,0,nz);\n"
    "      uvs.push(i/segs, y===half?1:0);\n"
    "    }\n"
    "  }\n"
    "  const sv=(segs+1)*2;\n"
    "  for(let i=0;i<segs;i++){\n"
    "    const a=i*2,b=a+1,c=a+2,d=a+3;\n"
    "    idx.push(a,b,c, b,d,c);\n"
    "  }\n"
    "  // Top cap\n"
    "  const ti=sv; let vi=ti;\n"
    "  pos.push(0,half,0); nor.push(0,1,0); uvs.push(.5,.5);\n"
    "  vi++;\n"
    "  for(let i=0;i<=segs;i++){\n"
    "    const theta=2*Math.PI*i/segs;\n"
    "    pos.push(rTop*Math.cos(theta),half,rTop*Math.sin(theta));\n"
    "    nor.push(0,1,0); uvs.push(.5+.5*Math.cos(theta),.5+.5*Math.sin(theta));\n"
    "    vi++;\n"
    "  }\n"
    "  for(let i=0;i<segs;i++) idx.push(ti, ti+1+i+1, ti+1+i);\n"
    "  // Bottom cap\n"
    "  const bi=vi;\n"
    "  pos.push(0,-half,0); nor.push(0,-1,0); uvs.push(.5,.5);\n"
    "  vi++;\n"
    "  for(let i=0;i<=segs;i++){\n"
    "    const theta=2*Math.PI*i/segs;\n"
    "    pos.push(rBot*Math.cos(theta),-half,rBot*Math.sin(theta));\n"
    "    nor.push(0,-1,0); uvs.push(.5+.5*Math.cos(theta),.5+.5*Math.sin(theta));\n"
    "    vi++;\n"
    "  }\n"
    "  for(let i=0;i<segs;i++) idx.push(bi, bi+1+i, bi+1+i+1);\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── CONO ────────────────────────────────────────────────────\n"
    "function genCone(r=0.7, h=1.618, segs=32) {\n"
    "  return genCylinder(0, r, h, segs);\n"
    "}\n"
    "\n"
    "// ── TORO ────────────────────────────────────────────────────\n"
    "function genTorus(R=0.7, r=0.25, tubeSeg=32, radSeg=24) {\n"
    "  const pos=[],nor=[],uvs=[],idx=[];\n"
    "  for(let j=0;j<=tubeSeg;j++){\n"
    "    const v=j/tubeSeg, phi=2*Math.PI*v;\n"
    "    for(let i=0;i<=radSeg;i++){\n"
    "      const u=i/radSeg, theta=2*Math.PI*u;\n"
    "      const cx=(R+r*Math.cos(phi))*Math.cos(theta);\n"
    "      const cy=r*Math.sin(phi);\n"
    "      const cz=(R+r*Math.cos(phi))*Math.sin(theta);\n"
    "      pos.push(cx,cy,cz);\n"
    "      const nx=Math.cos(phi)*Math.cos(theta);\n"
    "      const ny=Math.sin(phi);\n"
    "      const nz=Math.cos(phi)*Math.sin(theta);\n"
    "      nor.push(nx,ny,nz); uvs.push(u,v);\n"
    "    }\n"
    "  }\n"
    "  for(let j=0;j<tubeSeg;j++) for(let i=0;i<radSeg;i++){\n"
    "    const a=j*(radSeg+1)+i;\n"
    "    idx.push(a,a+radSeg+1,a+1, a+1,a+radSeg+1,a+radSeg+2);\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── PLANO ───────────────────────────────────────────────────\n"
    "function genPlane(w=2, d=2, seg=1) {\n"
    "  const pos=[],nor=[],uvs=[],idx=[];\n"
    "  const hw=w*.5, hd=d*.5;\n"
    "  for(let j=0;j<=seg;j++) for(let i=0;i<=seg;i++){\n"
    "    const x=-hw+w*i/seg, z=-hd+d*j/seg;\n"
    "    pos.push(x,0,z); nor.push(0,1,0); uvs.push(i/seg,j/seg);\n"
    "  }\n"
    "  for(let j=0;j<seg;j++) for(let i=0;i<seg;i++){\n"
    "    const a=j*(seg+1)+i;\n"
    "    idx.push(a,a+seg+1,a+1, a+1,a+seg+1,a+seg+2);\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── Cargar primitiva en el visor ─────────────────────────────\n"
    "window.rv3dLoadPrimitive = function(type) {\n"
    "  if (!gl) return;\n"
    "  // Close geo menu\n"
    "  document.getElementById('rv3d-geo-menu').classList.remove('open');\n"
    "  // Clear old\n"
    "  meshes.forEach(m => { if(m.vbuf) gl.deleteBuffer(m.vbuf); if(m.ibuf) gl.deleteBuffer(m.ibuf); });\n"
    "  meshes = [];\n"
    "\n"
    "  let geo;\n"
    "  const names = { sphere:'Esfera UV', icosphere:'Icósfera φ', dodecahedron:'Dodecaedro',\n"
    "                   cube:'Cubo', cylinder:'Cilindro', cone:'Cono φ', torus:'Toro', plane:'Plano',\n"
    "                   torusknot:'Nudo Tórico φ', capsule:'Cápsula', helix:'Hélice ADN', star:'Estrella' };\n"
    "  switch(type) {\n"
    "    case 'sphere':       geo = genSphere(1,32,32); break;\n"
    "    case 'icosphere':    geo = genIcosphere(1,3); break;\n"
    "    case 'dodecahedron': geo = genDodecahedron(1); break;\n"
    "    case 'cube':         geo = genCube(1.6); break;\n"
    "    case 'cylinder':     geo = genCylinder(0.5,0.5,2,48); break;\n"
    "    case 'cone':         geo = genCone(0.7,1.618,48); break;\n"
    "    case 'torus':        geo = genTorus(0.7,0.28,48,32); break;\n"
    "    case 'plane':        geo = genPlane(2.5,2.5,8); break;\n"
    "    case 'torusknot':    geo = genTorusKnot(0.7, 0.22, 2, 3, 128, 16); break;\n"
    "    case 'capsule':      geo = genCapsule(0.5, 1.2, 32, 12); break;\n"
    "    case 'helix':        geo = genHelix(0.7, 0.14, 3, 200, 12); break;\n"
    "    case 'star':         geo = genStar(1.0, 0.42, 6, 0.35); break;\n"
    "    default:             geo = genSphere(1,24,24);\n"
    "  }\n"
    "\n"
    "  const buf = uploadMesh(geo.pos, geo.nor, geo.uvs, geo.idx);\n"
    "  if (!buf) return;\n"
    "\n"
    "  meshes.push({\n"
    "    vbuf: buf.vbuf, ibuf: buf.ibuf,\n"
    "    indexCount: buf.indexCount, vertCount: buf.vertCount,\n"
    "    color: [0.784, 0.644, 0.353],  // oro suave\n"
    "    metalness: 0.85, roughness: 0.18,\n"
    "    visible: true,\n"
    "    name: names[type] || type,\n"
    "    tris: Math.round((buf.indexCount||buf.vertCount)/3),\n"
    "    bounds: { min:[-1,-1,-1], max:[1,1,1] }\n"
    "  });\n"
    "\n"
    "  // Scene setup\n"
    "  sceneCenter=[0,0,0]; sceneDiam=2;\n"
    "  sph.radius=4; target[0]=target[1]=target[2]=0;\n"
    "  modelLoaded=true; autoRotate=true;\n"
    "\n"
    "  // Hide open screen\n"
    "  document.getElementById('rv3d-open-screen').style.display='none';\n"
    "  const ld=document.getElementById('rv3d-loading'); if(ld) ld.style.display='none';\n"
    "\n"
    "  // Update HUD\n"
    "  const hu=document.getElementById('rv3d-hud'); if(hu) hu.style.display='block';\n"
    "  const fp=document.getElementById('rv3d-fps'); if(fp) fp.style.display='block';\n"
    "  document.getElementById('rv3d-h-meshes').textContent=1;\n"
    "  document.getElementById('rv3d-h-tris').textContent=meshes[0].tris;\n"
    "  document.getElementById('rv3d-h-mats').textContent=1;\n"
    "  document.getElementById('rv3d-h-anims').textContent='—';\n"
    "  document.getElementById('rv3d-file-name').textContent=names[type]||type;\n"
    "  document.getElementById('rv3d-file-meta').textContent='primitiva · φ';\n"
    "\n"
    "  buildRv3dMeshList();\n"
    "  rv3dToast('⬡ ' + (names[type]||type) + ' · φ');\n"
    "};\n"
    "\n"
    "// ── Toggle geo menu ─────────────────────────────────────────\n"
    "window.rv3dToggleGeoMenu = function() {\n"
    "  const m = document.getElementById('rv3d-geo-menu');\n"
    "  m.classList.toggle('open');\n"
    "  // close on outside click\n"
    "  if (m.classList.contains('open')) {\n"
    "    setTimeout(()=>{ document.addEventListener('click', function _close(e){\n"
    "      if(!m.contains(e.target) && e.target.id!=='rv3d-geo-btn'){\n"
    "        m.classList.remove('open');\n"
    "        document.removeEventListener('click',_close);\n"
    "      }\n"
    "    }); }, 10);\n"
    "  }\n"
    "};\n"
    "\n"
    "// ── CAMERA PRESETS ────────────────────────────────────────────\n"
    "window.rv3dSetView = function(preset) {\n"
    "  const r = sceneDiam * 2.4;\n"
    "  switch(preset) {\n"
    "    case 'front':  sph.theta = 0;               sph.phi = Math.PI/2; sph.radius = r; break;\n"
    "    case 'back':   sph.theta = Math.PI;          sph.phi = Math.PI/2; sph.radius = r; break;\n"
    "    case 'top':    sph.theta = 0;               sph.phi = 0.05;      sph.radius = r; break;\n"
    "    case 'right':  sph.theta = -Math.PI/2;       sph.phi = Math.PI/2; sph.radius = r; break;\n"
    "    case 'left':   sph.theta = Math.PI/2;        sph.phi = Math.PI/2; sph.radius = r; break;\n"
    "    case 'iso':    sph.theta = Math.PI*0.25;     sph.phi = 1.05;      sph.radius = r; break;\n"
    "  }\n"
    "  target[0] = sceneCenter[0]; target[1] = sceneCenter[1]; target[2] = sceneCenter[2];\n"
    "  autoRotate = false;\n"
    "  const ae = document.getElementById('rv3d-autorot'); if(ae) ae.checked = false;\n"
    "  rv3dToast('Vista · ' + preset.toUpperCase());\n"
    "};\n"
    "\n"
    "// ── ENV PRESETS ───────────────────────────────────────────────\n"
    "window.rv3dApplyEnvPreset = function(preset) {\n"
    "  const cw = document.getElementById('rv3d-canvas-wrap');\n"
    "  cw.classList.remove('env-sky','env-studio');\n"
    "  document.getElementById('rv3d-env-btn')?.classList.remove('env-on');\n"
    "  const presets = {\n"
    "    void:   { bg:[0.015,0.012,0.02],  amb:0.35, kc:[0.9,0.88,0.85], ki:0.9,  rc:[0.5,0.4,0.7],  ri:0.2  },\n"
    "    studio: { bg:[0.06,0.04,0.02],   amb:0.4,  kc:[1.0,0.96,0.88], ki:1.5,  rc:[0.8,0.66,0.3], ri:0.45 },\n"
    "    sky:    { bg:[0.03,0.08,0.13],   amb:0.7,  kc:[0.85,0.92,1.0], ki:1.4,  rc:[0.4,0.6,1.0],  ri:0.5  },\n"
    "    forge:  { bg:[0.08,0.02,0.015],  amb:0.6,  kc:[1.0,0.5,0.2],   ki:1.8,  rc:[1.0,0.3,0.1],  ri:0.6  },\n"
    "    ice:    { bg:[0.04,0.08,0.12],   amb:0.65, kc:[0.8,0.95,1.0],  ki:1.2,  rc:[0.6,0.9,1.0],  ri:0.4  },\n"
    "    neon:   { bg:[0.02,0.01,0.05],   amb:0.3,  kc:[0.8,0.2,1.0],   ki:1.6,  rc:[0.1,0.8,1.0],  ri:0.8  },\n"
    "  };\n"
    "  const p = presets[preset];\n"
    "  if (!p) return;\n"
    "  bgColor = p.bg;\n"
    "  lights.amb.int = p.amb;\n"
    "  lights.key.col = p.kc; lights.key.int = p.ki;\n"
    "  lights.rim.col = p.rc; lights.rim.int = p.ri;\n"
    "  if (preset === 'sky')    cw.classList.add('env-sky');\n"
    "  if (preset === 'studio') cw.classList.add('env-studio');\n"
    "  // Sync sliders\n"
    "  ['amb','key','fill','rim'].forEach(k => {\n"
    "    const sl = document.getElementById('rv3d-'+k);\n"
    "    const vl = document.getElementById('rv3d-'+k+'-v');\n"
    "    if(sl && k==='amb') { sl.value=lights.amb.int; if(vl) vl.textContent=lights.amb.int.toFixed(1); }\n"
    "    if(sl && k==='key') { sl.value=lights.key.int; if(vl) vl.textContent=lights.key.int.toFixed(1); }\n"
    "    if(sl && k==='rim') { sl.value=lights.rim.int; if(vl) vl.textContent=lights.rim.int.toFixed(1); }\n"
    "  });\n"
    "  rv3dToast('Entorno · ' + preset.toUpperCase());\n"
    "};\n"
    "\n"
    "// ── FULLSCREEN ────────────────────────────────────────────────\n"
    "window.rv3dToggleFullscreen = function() {\n"
    "  const shell = document.getElementById('rv3d-shell');\n"
    "  const btn   = document.getElementById('rv3d-fs-btn');\n"
    "  if (!shell) return;\n"
    "  const isFs = shell.classList.toggle('rv3d-fullscreen');\n"
    "  if (btn) btn.textContent = isFs ? '⛶' : '⛶';\n"
    "  if (btn) btn.style.color = isFs ? '#c8a45a' : '';\n"
    "  if (isFs) {\n"
    "    // prevent body scroll\n"
    "    document.body.style.overflow = 'hidden';\n"
    "    setTimeout(() => { resize3D(); }, 50);\n"
    "  } else {\n"
    "    document.body.style.overflow = '';\n"
    "    setTimeout(() => { resize3D(); }, 50);\n"
    "  }\n"
    "  rv3dToast(isFs ? 'Pantalla completa' : 'Ventana normal');\n"
    "};\n"
    "\n"
    "// ── EXPLODE MODE ──────────────────────────────────────────────\n"
    "let explodeAmount = 0;\n"
    "window.rv3dToggleExplode = function() {\n"
    "  const btn = document.getElementById('rv3d-explode-btn');\n"
    "  const sl  = document.getElementById('rv3d-explode-amt');\n"
    "  const isActive = explodeAmount > 0;\n"
    "  if (isActive) {\n"
    "    explodeAmount = 0;\n"
    "    if (sl) sl.value = 0;\n"
    "    if (btn) btn.classList.remove('active');\n"
    "    document.getElementById('rv3d-explode-v').textContent = '0.0';\n"
    "  } else {\n"
    "    explodeAmount = 1.0;\n"
    "    if (sl) sl.value = 1.0;\n"
    "    if (btn) btn.classList.add('active');\n"
    "    document.getElementById('rv3d-explode-v').textContent = '1.0';\n"
    "  }\n"
    "  rv3dToast(explodeAmount > 0 ? 'Explosión ON' : 'Explosión OFF');\n"
    "};\n"
    "\n"
    "// Bind explode slider\n"
    "(function(){\n"
    "  const sl = document.getElementById('rv3d-explode-amt');\n"
    "  const vl = document.getElementById('rv3d-explode-v');\n"
    "  if(!sl) return;\n"
    "  sl.addEventListener('input', () => {\n"
    "    explodeAmount = parseFloat(sl.value);\n"
    "    if(vl) vl.textContent = explodeAmount.toFixed(1);\n"
    "    const btn = document.getElementById('rv3d-explode-btn');\n"
    "    if(btn) btn.classList.toggle('active', explodeAmount > 0);\n"
    "  });\n"
    "})();\n"
    "\n"
    "// ── SHOW ALL MESHES ────────────────────────────────────────────\n"
    "window.rv3dShowAllMeshes = function() {\n"
    "  meshes.forEach(m => m.visible = true);\n"
    "  document.querySelectorAll('.rv3d-mesh-item').forEach(el => {\n"
    "    el.classList.remove('hidden','isolated');\n"
    "    const vis = el.querySelector('.rv3d-mesh-vis');\n"
    "    if(vis) vis.classList.remove('off');\n"
    "  });\n"
    "  rv3dToast('Todos visibles');\n"
    "};\n"
    "\n"
    "// ── DEEP CONTROLS: near/far ────────────────────────────────────\n"
    "(function bindDepth(){\n"
    "  const nsl = document.getElementById('rv3d-near');\n"
    "  const fsl = document.getElementById('rv3d-far');\n"
    "  if(nsl) nsl.addEventListener('input', e => { nearPlane = parseFloat(e.target.value); document.getElementById('rv3d-near-v').textContent = parseFloat(e.target.value).toFixed(3); });\n"
    "  if(fsl) fsl.addEventListener('input', e => { farPlane  = parseFloat(e.target.value); document.getElementById('rv3d-far-v').textContent  = parseFloat(e.target.value).toFixed(0); });\n"
    "})();\n"
    "\n"
    "// ── POST-FX SYSTEM (2D canvas overlay) ────────────────────────\n"
    "const fxState = {\n"
    "  vignette: false, vigStr: 0.5,\n"
    "  grain: false,    grainStr: 0.3,\n"
    "  aberr: false,    aberrStr: 2.0,\n"
    "  bloom: false,    bloomStr: 0.6,\n"
    "  scan: false,     scanStr: 0.08,\n"
    "  sat: 1.0, contrast: 1.0,\n"
    "  tint: [1,1,1]\n"
    "};\n"
    "\n"
    "let fxCanvas = null, fxCtx = null, fxAnimId = null;\n"
    "\n"
    "function initFXCanvas() {\n"
    "  fxCanvas = document.getElementById('rv3d-fx-canvas');\n"
    "  if (!fxCanvas) return;\n"
    "  fxCtx = fxCanvas.getContext('2d');\n"
    "}\n"
    "\n"
    "function syncFXCanvas() {\n"
    "  if (!fxCanvas) return;\n"
    "  fxCanvas.width  = fxCanvas.offsetWidth  * Math.min(devicePixelRatio, 2);\n"
    "  fxCanvas.height = fxCanvas.offsetHeight * Math.min(devicePixelRatio, 2);\n"
    "}\n"
    "\n"
    "function hasFX() {\n"
    "  return fxState.vignette || fxState.grain || fxState.scan || fxState.aberr;\n"
    "}\n"
    "\n"
    "function renderFX() {\n"
    "  if (!fxCtx || !fxCanvas) return;\n"
    "  const w = fxCanvas.width, h = fxCanvas.height;\n"
    "  fxCtx.clearRect(0, 0, w, h);\n"
    "\n"
    "  // Vignette\n"
    "  if (fxState.vignette) {\n"
    "    const grd = fxCtx.createRadialGradient(w/2,h/2, h*0.25, w/2,h/2, h*0.75);\n"
    "    grd.addColorStop(0, 'rgba(0,0,0,0)');\n"
    "    grd.addColorStop(1, `rgba(0,0,0,${fxState.vigStr * 0.85})`);\n"
    "    fxCtx.fillStyle = grd;\n"
    "    fxCtx.fillRect(0, 0, w, h);\n"
    "  }\n"
    "\n"
    "  // Scanlines\n"
    "  if (fxState.scan) {\n"
    "    fxCtx.globalAlpha = fxState.scanStr;\n"
    "    for (let y = 0; y < h; y += 4) {\n"
    "      fxCtx.fillStyle = 'rgba(0,0,0,0.9)';\n"
    "      fxCtx.fillRect(0, y, w, 2);\n"
    "    }\n"
    "    fxCtx.globalAlpha = 1;\n"
    "  }\n"
    "\n"
    "  // Film grain (animated)\n"
    "  if (fxState.grain) {\n"
    "    const imgData = fxCtx.getImageData(0, 0, w, h);\n"
    "    const d = imgData.data;\n"
    "    const gs = fxState.grainStr * 80;\n"
    "    for (let i = 0; i < d.length; i += 4) {\n"
    "      const noise = (Math.random() - 0.5) * gs;\n"
    "      d[i]   = Math.max(0, Math.min(255, d[i]   + noise));\n"
    "      d[i+1] = Math.max(0, Math.min(255, d[i+1] + noise));\n"
    "      d[i+2] = Math.max(0, Math.min(255, d[i+2] + noise));\n"
    "    }\n"
    "    fxCtx.putImageData(imgData, 0, 0);\n"
    "  }\n"
    "\n"
    "  // Chromatic aberration overlay glow\n"
    "  if (fxState.aberr) {\n"
    "    const a = fxState.aberrStr / 20;\n"
    "    const grd2 = fxCtx.createRadialGradient(w/2, h/2, 0, w/2, h/2, Math.max(w,h)/2);\n"
    "    grd2.addColorStop(0, 'rgba(0,0,0,0)');\n"
    "    grd2.addColorStop(0.7, 'rgba(0,0,0,0)');\n"
    "    grd2.addColorStop(1, `rgba(255,60,60,${a})`);\n"
    "    fxCtx.fillStyle = grd2;\n"
    "    fxCtx.fillRect(0, 0, w, h);\n"
    "    const grd3 = fxCtx.createRadialGradient(w/2, h/2, 0, w/2, h/2, Math.max(w,h)/2);\n"
    "    grd3.addColorStop(0, 'rgba(0,0,0,0)');\n"
    "    grd3.addColorStop(0.7, 'rgba(0,0,0,0)');\n"
    "    grd3.addColorStop(1, `rgba(60,60,255,${a})`);\n"
    "    fxCtx.fillStyle = grd3;\n"
    "    fxCtx.globalCompositeOperation = 'screen';\n"
    "    fxCtx.fillRect(0, 0, w, h);\n"
    "    fxCtx.globalCompositeOperation = 'source-over';\n"
    "  }\n"
    "\n"
    "  if (hasFX()) requestAnimationFrame(renderFX);\n"
    "  else { fxAnimId = null; }\n"
    "}\n"
    "\n"
    "function startFX() {\n"
    "  if (!fxCanvas) initFXCanvas();\n"
    "  syncFXCanvas();\n"
    "  fxCanvas.style.display = 'block';\n"
    "  if (!fxAnimId) {\n"
    "    fxAnimId = 1;\n"
    "    renderFX();\n"
    "  }\n"
    "}\n"
    "function stopFX() {\n"
    "  if (fxCanvas) fxCanvas.style.display = 'none';\n"
    "  fxAnimId = null;\n"
    "}\n"
    "function updateFXState() {\n"
    "  if (hasFX()) startFX();\n"
    "  else stopFX();\n"
    "}\n"
    "\n"
    "window.rv3dResetFX = function() {\n"
    "  Object.assign(fxState, { vignette:false, vigStr:0.5, grain:false, grainStr:0.3, aberr:false, aberrStr:2.0, bloom:false, bloomStr:0.6, scan:false, scanStr:0.08, sat:1.0, contrast:1.0, tint:[1,1,1] });\n"
    "  ['rv3d-fx-vignette','rv3d-fx-grain','rv3d-fx-aberr','rv3d-fx-bloom','rv3d-fx-scan'].forEach(id => {\n"
    "    const el = document.getElementById(id); if(el) el.checked = false;\n"
    "  });\n"
    "  [['rv3d-fx-vig-str',0.5,'rv3d-fx-vig-v'], ['rv3d-fx-grain-str',0.3,'rv3d-fx-grain-v'],\n"
    "   ['rv3d-fx-aberr-str',2.0,'rv3d-fx-aberr-v'], ['rv3d-fx-bloom-str',0.6,'rv3d-fx-bloom-v'],\n"
    "   ['rv3d-fx-scan-str',0.08,'rv3d-fx-scan-v'], ['rv3d-fx-sat',1,'rv3d-fx-sat-v'],\n"
    "   ['rv3d-fx-contrast',1,'rv3d-fx-contrast-v']].forEach(([id,val,vid]) => {\n"
    "    const el = document.getElementById(id); if(el) el.value = val;\n"
    "    const vl = document.getElementById(vid); if(vl) vl.textContent = val.toFixed(2);\n"
    "  });\n"
    "  updateFXState();\n"
    "  rv3dToast('FX reseteado');\n"
    "};\n"
    "\n"
    "// Bind FX controls\n"
    "(function bindFX(){\n"
    "  function bToggle(id, key) {\n"
    "    const el = document.getElementById(id);\n"
    "    if(el) el.addEventListener('change', e => { fxState[key] = e.target.checked; updateFXState(); });\n"
    "  }\n"
    "  function bSlider(id, key, valId, dec=2) {\n"
    "    const el = document.getElementById(id); const vl = document.getElementById(valId);\n"
    "    if(el) el.addEventListener('input', e => {\n"
    "      fxState[key] = parseFloat(e.target.value);\n"
    "      if(vl) vl.textContent = fxState[key].toFixed(dec);\n"
    "      if (hasFX() && !fxAnimId) startFX();\n"
    "    });\n"
    "  }\n"
    "  bToggle('rv3d-fx-vignette','vignette'); bSlider('rv3d-fx-vig-str','vigStr','rv3d-fx-vig-v');\n"
    "  bToggle('rv3d-fx-grain','grain');       bSlider('rv3d-fx-grain-str','grainStr','rv3d-fx-grain-v');\n"
    "  bToggle('rv3d-fx-aberr','aberr');       bSlider('rv3d-fx-aberr-str','aberrStr','rv3d-fx-aberr-v');\n"
    "  bToggle('rv3d-fx-bloom','bloom');       bSlider('rv3d-fx-bloom-str','bloomStr','rv3d-fx-bloom-v');\n"
    "  bToggle('rv3d-fx-scan','scan');         bSlider('rv3d-fx-scan-str','scanStr','rv3d-fx-scan-v');\n"
    "  bSlider('rv3d-fx-sat','sat','rv3d-fx-sat-v');\n"
    "  bSlider('rv3d-fx-contrast','contrast','rv3d-fx-contrast-v');\n"
    "  const tintEl = document.getElementById('rv3d-fx-tint');\n"
    "  if(tintEl) tintEl.addEventListener('input', e => { fxState.tint = hexToRGB(e.target.value); });\n"
    "})();\n"
    "\n"
    "// ── NEW GEOMETRY GENERATORS ─────────────────────────────────────\n"
    "\n"
    "// Torus Knot (p,q)\n"
    "function genTorusKnot(R=0.7, r=0.2, p=2, q=3, tubeSeg=128, radSeg=16) {\n"
    "  const pos=[], nor=[], uvs=[], idx=[];\n"
    "  function knotPoint(t) {\n"
    "    const phi = t * 2 * Math.PI;\n"
    "    const x = Math.cos(phi) * (R + r * Math.cos(q * phi / p));\n"
    "    const y = Math.sin(phi) * (R + r * Math.cos(q * phi / p));\n"
    "    const z = r * Math.sin(q * phi / p);\n"
    "    return [x, y, z];\n"
    "  }\n"
    "  for (let j = 0; j <= tubeSeg; j++) {\n"
    "    const t = j / tubeSeg;\n"
    "    const P0 = knotPoint(t);\n"
    "    const P1 = knotPoint(t + 0.001);\n"
    "    const T = normalize3v([P1[0]-P0[0], P1[1]-P0[1], P1[2]-P0[2]]);\n"
    "    const N0 = normalize3v([-T[1], T[0], 0]);\n"
    "    const B  = normalize3v([T[1]*N0[2]-T[2]*N0[1], T[2]*N0[0]-T[0]*N0[2], T[0]*N0[1]-T[1]*N0[0]]);\n"
    "    for (let i = 0; i <= radSeg; i++) {\n"
    "      const th = i / radSeg * 2 * Math.PI;\n"
    "      const cx = Math.cos(th) * r * 0.5, cy = Math.sin(th) * r * 0.5;\n"
    "      const nx = cx * N0[0] + cy * B[0];\n"
    "      const ny = cx * N0[1] + cy * B[1];\n"
    "      const nz = cx * N0[2] + cy * B[2];\n"
    "      pos.push(P0[0]+nx, P0[1]+ny, P0[2]+nz);\n"
    "      const n = normalize3v([nx, ny, nz]);\n"
    "      nor.push(n[0], n[1], n[2]);\n"
    "      uvs.push(i/radSeg, t);\n"
    "    }\n"
    "  }\n"
    "  for (let j = 0; j < tubeSeg; j++) {\n"
    "    for (let i = 0; i < radSeg; i++) {\n"
    "      const a = j*(radSeg+1)+i;\n"
    "      idx.push(a,a+radSeg+1,a+1, a+1,a+radSeg+1,a+radSeg+2);\n"
    "    }\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// Capsule\n"
    "function genCapsule(r=0.5, h=1.5, segs=32, caps=16) {\n"
    "  const { pos:sp, nor:sn, uvs:su, idx:si } = genCylinder(r, r, h, segs);\n"
    "  // top cap hemisphere\n"
    "  const half = h * 0.5;\n"
    "  for (let i = 0; i <= caps; i++) {\n"
    "    const phi = Math.PI * 0.5 * i / caps;\n"
    "    for (let j = 0; j <= segs; j++) {\n"
    "      const theta = 2 * Math.PI * j / segs;\n"
    "      const x = r * Math.cos(phi) * Math.cos(theta);\n"
    "      const y = r * Math.sin(phi) + half;\n"
    "      const z = r * Math.cos(phi) * Math.sin(theta);\n"
    "      sp.push(x,y,z); sn.push(x/r, (y-half)/r, z/r); su.push(j/segs, 0.5 + phi/Math.PI);\n"
    "    }\n"
    "  }\n"
    "  // bottom hemisphere\n"
    "  for (let i = 0; i <= caps; i++) {\n"
    "    const phi = Math.PI * 0.5 * (1 - i/caps);\n"
    "    for (let j = 0; j <= segs; j++) {\n"
    "      const theta = 2 * Math.PI * j / segs;\n"
    "      const x = r * Math.cos(phi) * Math.cos(theta);\n"
    "      const y = -r * Math.sin(phi) - half;\n"
    "      const z = r * Math.cos(phi) * Math.sin(theta);\n"
    "      sp.push(x,y,z); sn.push(x/r, (y+half)/r, z/r); su.push(j/segs, 0.5 - phi/Math.PI);\n"
    "    }\n"
    "  }\n"
    "  return { pos:sp, nor:sn, uvs:su, idx:si };\n"
    "}\n"
    "\n"
    "// Helix\n"
    "function genHelix(r=0.7, tubeR=0.12, turns=3, segs=200, radSeg=12) {\n"
    "  const pos=[], nor=[], uvs=[], idx=[];\n"
    "  const totalLen = turns * 2 * Math.PI;\n"
    "  for (let j = 0; j <= segs; j++) {\n"
    "    const t = j / segs;\n"
    "    const phi = t * totalLen;\n"
    "    const Cx = r * Math.cos(phi);\n"
    "    const Cy = (t - 0.5) * turns * 1.2;\n"
    "    const Cz = r * Math.sin(phi);\n"
    "    const Tx = -r * Math.sin(phi);\n"
    "    const Ty = turns * 1.2 / totalLen * 2 * Math.PI;\n"
    "    const Tz = r * Math.cos(phi);\n"
    "    const Tn = normalize3v([Tx, Ty, Tz]);\n"
    "    const Nn = normalize3v([-Tn[1], Tn[0], 0]);\n"
    "    const Bn = normalize3v([Tn[1]*Nn[2]-Tn[2]*Nn[1], Tn[2]*Nn[0]-Tn[0]*Tn[2], Tn[0]*Nn[1]-Tn[1]*Nn[0]]);\n"
    "    for (let i = 0; i <= radSeg; i++) {\n"
    "      const a = i / radSeg * 2 * Math.PI;\n"
    "      const ca = Math.cos(a) * tubeR, sa = Math.sin(a) * tubeR;\n"
    "      const nx = ca * Nn[0] + sa * Bn[0];\n"
    "      const ny = ca * Nn[1] + sa * Bn[1];\n"
    "      const nz = ca * Nn[2] + sa * Bn[2];\n"
    "      pos.push(Cx+nx, Cy+ny, Cz+nz);\n"
    "      const n = normalize3v([nx,ny,nz]);\n"
    "      nor.push(n[0],n[1],n[2]);\n"
    "      uvs.push(i/radSeg, t);\n"
    "    }\n"
    "  }\n"
    "  for (let j = 0; j < segs; j++) {\n"
    "    for (let i = 0; i < radSeg; i++) {\n"
    "      const a = j*(radSeg+1)+i;\n"
    "      idx.push(a,a+radSeg+1,a+1, a+1,a+radSeg+1,a+radSeg+2);\n"
    "    }\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// Star (extruded)\n"
    "function genStar(outerR=1, innerR=0.4, pts=6, depth=0.3) {\n"
    "  const pos=[], nor=[], uvs=[], idx=[];\n"
    "  const step = Math.PI / pts;\n"
    "  function addFace(verts, n) {\n"
    "    const base = pos.length / 3;\n"
    "    verts.forEach(([x,y,z]) => { pos.push(x,y,z); nor.push(n[0],n[1],n[2]); uvs.push((x+1)/2,(z+1)/2); });\n"
    "    for (let i = 1; i < verts.length - 1; i++) idx.push(base, base+i, base+i+1);\n"
    "  }\n"
    "  const topVerts = [], botVerts = [];\n"
    "  for (let i = 0; i < pts*2; i++) {\n"
    "    const a = i * step;\n"
    "    const r = (i % 2 === 0) ? outerR : innerR;\n"
    "    topVerts.push([r*Math.cos(a), depth/2, r*Math.sin(a)]);\n"
    "    botVerts.push([r*Math.cos(a), -depth/2, r*Math.sin(a)]);\n"
    "  }\n"
    "  addFace([[0,depth/2,0], ...topVerts], [0,1,0]);\n"
    "  addFace([[0,-depth/2,0], ...botVerts.slice().reverse()], [0,-1,0]);\n"
    "  for (let i = 0; i < pts*2; i++) {\n"
    "    const next = (i+1) % (pts*2);\n"
    "    const t0 = topVerts[i], t1 = topVerts[next];\n"
    "    const b0 = botVerts[i], b1 = botVerts[next];\n"
    "    const base = pos.length / 3;\n"
    "    const n = normalize3v([(t0[0]+t1[0])/2, 0, (t0[2]+t1[2])/2]);\n"
    "    [t0,t1,b1,b0].forEach(([x,y,z]) => { pos.push(x,y,z); nor.push(n[0],n[1],n[2]); uvs.push(0,0); });\n"
    "    idx.push(base,base+1,base+2, base,base+2,base+3);\n"
    "  }\n"
    "  return { pos, nor, uvs, idx };\n"
    "}\n"
    "\n"
    "// ── ENV toggle: cycle background environments ────────────────\n"
    "const envModes = ['dark','studio','sky'];\n"
    "let envIdx = 0;\n"
    "(function initEnv(){\n"
    "  const btn = document.getElementById('rv3d-env-btn');\n"
    "  if(!btn) return;\n"
    "  btn.addEventListener('click', ()=>{\n"
    "    envIdx = (envIdx+1) % envModes.length;\n"
    "    const e = envModes[envIdx];\n"
    "    rv3dApplyEnvPreset(e === 'dark' ? 'void' : e);\n"
    "    btn.classList.toggle('env-on', e !== 'dark');\n"
    "    rv3dToast('ENV · ' + e.toUpperCase());\n"
    "  });\n"
    "})();\n"
    "\n"
    "// ── Measure tool ─────────────────────────────────────────────\n"
    "(function initMeasure(){\n"
    "  const btn = document.getElementById('rv3d-measure-btn');\n"
    "  const mc  = document.getElementById('rv3d-measure-canvas');\n"
    "  const ind = document.getElementById('rv3d-measure-indicator');\n"
    "  if(!btn||!mc||!ind) return;\n"
    "\n"
    "  let measureMode=false, ptA=null, ptB=null;\n"
    "  let mctx=null;\n"
    "\n"
    "  function syncMeasureCanvas(){\n"
    "    mc.width  = mc.offsetWidth  * Math.min(devicePixelRatio,2);\n"
    "    mc.height = mc.offsetHeight * Math.min(devicePixelRatio,2);\n"
    "    mctx = mc.getContext('2d');\n"
    "  }\n"
    "\n"
    "  function drawMeasure(){\n"
    "    if(!mctx) return;\n"
    "    mctx.clearRect(0,0,mc.width,mc.height);\n"
    "    const dpr=Math.min(devicePixelRatio,2);\n"
    "    if(ptA){\n"
    "      mctx.beginPath();\n"
    "      mctx.arc(ptA.x*dpr,ptA.y*dpr,5*dpr,0,Math.PI*2);\n"
    "      mctx.fillStyle='rgba(0,184,204,.9)'; mctx.fill();\n"
    "    }\n"
    "    if(ptA&&ptB){\n"
    "      mctx.beginPath();\n"
    "      mctx.moveTo(ptA.x*dpr,ptA.y*dpr);\n"
    "      mctx.lineTo(ptB.x*dpr,ptB.y*dpr);\n"
    "      mctx.strokeStyle='rgba(0,184,204,.7)';\n"
    "      mctx.lineWidth=1.5*dpr;\n"
    "      mctx.setLineDash([4*dpr,4*dpr]);\n"
    "      mctx.stroke();\n"
    "      mctx.beginPath();\n"
    "      mctx.arc(ptB.x*dpr,ptB.y*dpr,5*dpr,0,Math.PI*2);\n"
    "      mctx.fillStyle='rgba(200,164,90,.9)'; mctx.fill();\n"
    "      // distance label (screen px for now)\n"
    "      const dx=ptB.x-ptA.x, dy=ptB.y-ptA.y;\n"
    "      const dist=Math.sqrt(dx*dx+dy*dy).toFixed(0);\n"
    "      const mx=(ptA.x+ptB.x)/2, my=(ptA.y+ptB.y)/2;\n"
    "      mctx.setLineDash([]);\n"
    "      mctx.font=`${9*dpr}px JetBrains Mono, monospace`;\n"
    "      mctx.fillStyle='rgba(200,164,90,1)';\n"
    "      mctx.textAlign='center';\n"
    "      mctx.fillText(dist+'px', mx*dpr, (my-8)*dpr);\n"
    "    }\n"
    "  }\n"
    "\n"
    "  btn.addEventListener('click',()=>{\n"
    "    measureMode=!measureMode;\n"
    "    ptA=ptB=null;\n"
    "    mc.classList.toggle('on',measureMode);\n"
    "    ind.classList.toggle('on',measureMode);\n"
    "    btn.classList.toggle('rv3d-btn-accent',measureMode);\n"
    "    btn.classList.toggle('rv3d-btn-ghost',!measureMode);\n"
    "    if(measureMode){ syncMeasureCanvas(); drawMeasure(); }\n"
    "    else { if(mctx) mctx.clearRect(0,0,mc.width,mc.height); }\n"
    "    rv3dToast(measureMode?'Medición ON — click para punto A':'Medición OFF');\n"
    "  });\n"
    "\n"
    "  mc.style.pointerEvents='none';\n"
    "  document.getElementById('rv3d-canvas')?.addEventListener('click',e=>{\n"
    "    if(!measureMode) return;\n"
    "    const rect=e.currentTarget.getBoundingClientRect();\n"
    "    const p={x:e.clientX-rect.left, y:e.clientY-rect.top};\n"
    "    if(!ptA){ ptA=p; rv3dToast('Punto A marcado — click para B'); }\n"
    "    else { ptB=p; }\n"
    "    drawMeasure();\n"
    "  });\n"
    "\n"
    "  new ResizeObserver(()=>{ if(measureMode) syncMeasureCanvas(); }).observe(document.getElementById('rv3d-canvas-wrap'));\n"
    "})();\n"
    "\n"
    "// ── Wire glow: add CSS class on canvas wrap when wire mode toggles ─\n"
    "(function patchWireToggle(){\n"
    "  const orig = window.rv3dTogglePanel;\n"
    "  const wBtn = document.getElementById('rv3d-wire-btn');\n"
    "  if(!wBtn) return;\n"
    "  const cw = document.getElementById('rv3d-canvas-wrap');\n"
    "  wBtn.addEventListener('click',()=>{\n"
    "    setTimeout(()=>{ cw.classList.toggle('wire-active', wireMode); },50);\n"
    "  });\n"
    "})();\n"
    "\n"
    "})(); // end primitives IIFE\n"
    "\n"
    "})(); // end main IIFE\n"
    "\n"
    "// ════════════════════════════════════════════════════════════════\n"
    "// §36 FACE ENGINE — Panel JS\n"
    "// ════════════════════════════════════════════════════════════════\n"
    "(function() {\n"
    "'use strict';\n"
    "\n"
    "const PHI = 1.6180339887498948482;\n"
    "\n"
    "// ── Definición de 22 landmarks craneales φ ────────────────────\n"
    "const CRANIAL = [\n"
    "  {id:'cranium_width',  lbl:'ANCHURA CRANEAL',  min:.14, max:.26, val:.19,  step:.001},\n"
    "  {id:'cranium_height', lbl:'ALTURA CRANEAL',   min:.10, max:.24, val:.17,  step:.001},\n"
    "  {id:'cranium_depth',  lbl:'PROF. CRANEAL',    min:.14, max:.24, val:.19,  step:.001},\n"
    "  {id:'face_phi_ratio', lbl:'RATIO φ FACIAL',   min:1.4, max:1.9, val:PHI,  step:.001},\n"
    "  {id:'interocular_dist',lbl:'DIST. OCULAR',    min:.06, max:.09, val:.065, step:.001},\n"
    "  {id:'eye_width',      lbl:'ANCHURA OJO',      min:.02, max:.04, val:.03,  step:.001},\n"
    "  {id:'orbital_depth',  lbl:'PROF. ÓRBITA',     min:.01, max:.03, val:.018, step:.001},\n"
    "  {id:'brow_protrusion',lbl:'ARCO SUPRAORB.',   min:.002,max:.015,val:.007, step:.001},\n"
    "  {id:'nose_length',    lbl:'LONG. NARIZ',      min:.04, max:.07, val:.052, step:.001},\n"
    "  {id:'nose_width',     lbl:'ANCHURA NARIZ',    min:.025,max:.05, val:.035, step:.001},\n"
    "  {id:'nasal_tip_proj', lbl:'PROY. PUNTA',      min:.01, max:.03, val:.018, step:.001},\n"
    "  {id:'mouth_width',    lbl:'ANCHURA BOCA',     min:.04, max:.07, val:.05,  step:.001},\n"
    "  {id:'lip_thickness_upper',lbl:'LAB. SUPERIOR',min:.004,max:.014,val:.008, step:.001},\n"
    "  {id:'lip_thickness_lower',lbl:'LAB. INFERIOR',min:.004,max:.016,val:.010, step:.001},\n"
    "  {id:'jaw_width',      lbl:'ANCHURA MANDÍB.',  min:.12, max:.18, val:.14,  step:.001},\n"
    "  {id:'jaw_angle',      lbl:'ÁNGULO MANDIB.',   min:100, max:145, val:125,  step:.5},\n"
    "  {id:'chin_projection',lbl:'PROYEC. MENTÓN',   min:.005,max:.025,val:.012, step:.001},\n"
    "  {id:'zygomatic_width',lbl:'ANCH. PÓMULOS',    min:.13, max:.18, val:.15,  step:.001},\n"
    "  {id:'zygomatic_height',lbl:'ALT. PÓMULOS',    min:.04, max:.08, val:.06,  step:.001},\n"
    "  {id:'neck_width',     lbl:'ANCHURA CUELLO',   min:.07, max:.13, val:.095, step:.001},\n"
    "  {id:'neck_length',    lbl:'LONG. CUELLO',     min:.06, max:.14, val:.10,  step:.001},\n"
    "];\n"
    "\n"
    "const ETHNO = [\n"
    "  {id:'melanin',          lbl:'MELANINA',         min:0, max:1, val:.35,  step:.01},\n"
    "  {id:'hemoglobin',       lbl:'HEMOGLOBINA',      min:0, max:1, val:.5,   step:.01},\n"
    "  {id:'carotene_concentration',lbl:'CAROTENO',    min:0, max:1, val:.15,  step:.01},\n"
    "  {id:'age_factor',       lbl:'EDAD',             min:0, max:1, val:.2,   step:.01},\n"
    "  {id:'gender_factor',    lbl:'GÉNERO (F→M)',      min:0, max:1, val:.5,   step:.01},\n"
    "];\n"
    "\n"
    "// 52 FACS AU — nombres abreviados\n"
    "const FACS = [\n"
    "  'AU01 Ceja Int↑','AU02 Ceja Ext↑','AU04 Ceja↓','AU05 Párpado↑',\n"
    "  'AU06 Mejilla↑','AU07 Párpado↓','AU09 Nariz↑','AU10 Labio Sup↑',\n"
    "  'AU11 Nasolabial','AU12 Sonrisa','AU13 Pómulo','AU14 Hoyuelo',\n"
    "  'AU15 Comisura↓','AU16 Labio Inf↓','AU17 Mentón↑','AU18 Labios',\n"
    "  'AU20 Labios→','AU22 Labios○','AU23 Labios↓','AU24 Presión Lab',\n"
    "  'AU25 Boca↓','AU26 Mandíb↓','AU27 Boca↓↓','AU28 Succión',\n"
    "  'AU41 Párp↓','AU42 Párp Mío','AU43 Cerrar Ojo','AU44 Parpadear',\n"
    "  'AU45 Guiño L','AU46 Guiño R','AU51 Cabeza←','AU52 Cabeza→',\n"
    "  'AU53 Cabeza↑','AU54 Cabeza↓','AU55 Inclinar←','AU56 Inclinar→',\n"
    "  'AU57 Adelantar','AU58 Retraer','L Desp X','L Desp Y',\n"
    "  'L Desp Z','R Desp X','R Desp Y','R Desp Z',\n"
    "  'L Rot X','L Rot Y','L Rot Z','R Rot X',\n"
    "  'R Rot Y','R Rot Z','Frown','Smile',\n"
    "];\n"
    "\n"
    "let faceWeights = new Float32Array(52);\n"
    "let faceParams  = {};\n"
    "let faceBuilt   = false;\n"
    "let faceTimer   = null;\n"
    "\n"
    "function makeFaceSlider(container, params) {\n"
    "  params.forEach(p => {\n"
    "    const row = document.createElement('div');\n"
    "    row.style.cssText = 'display:flex;align-items:center;gap:6px';\n"
    "    const lbl = document.createElement('span');\n"
    "    lbl.style.cssText = \"font-size:6.5px;letter-spacing:.8px;color:rgba(221,213,197,.35);font-family:'JetBrains Mono',monospace;width:90px;flex-shrink:0;text-align:right\";\n"
    "    lbl.textContent = p.lbl;\n"
    "    const sl = document.createElement('input');\n"
    "    sl.type='range'; sl.min=p.min; sl.max=p.max; sl.step=p.step; sl.value=p.val;\n"
    "    sl.style.cssText='flex:1;accent-color:#a888e8;height:2px';\n"
    "    const vl = document.createElement('span');\n"
    "    vl.style.cssText=\"font-size:7px;color:rgba(168,136,232,.7);font-family:'JetBrains Mono',monospace;width:36px;text-align:right;flex-shrink:0\";\n"
    "    vl.textContent = (+p.val).toFixed(3);\n"
    "    faceParams[p.id] = p.val;\n"
    "    sl.addEventListener('input', () => {\n"
    "      faceParams[p.id] = parseFloat(sl.value);\n"
    "      vl.textContent = (+sl.value).toFixed(3);\n"
    "    });\n"
    "    row.appendChild(lbl); row.appendChild(sl); row.appendChild(vl);\n"
    "    container.appendChild(row);\n"
    "  });\n"
    "}\n"
    "\n"
    "function makeFacsSliders() {\n"
    "  const c = document.getElementById('rv3d-face-facs'); if(!c) return;\n"
    "  const FACS_GROUPS = [0,8,16,24,32,40,48];\n"
    "  const FACS_GROUP_LABELS = ['PÁRPADOS·CEJAS','NARIZ·LABIOS','BOCA','OJOS·PARPADEO','CABEZA','OJOS IZQUIERDO','OJO DERECHO'];\n"
    "  FACS.forEach((name,i) => {\n"
    "    if (FACS_GROUPS.includes(i)) {\n"
    "      const grp = document.createElement('div');\n"
    "      grp.style.cssText=\"font-size:6px;letter-spacing:2px;color:rgba(168,136,232,.3);font-family:'JetBrains Mono',monospace;text-transform:uppercase;margin:6px 0 2px;padding-top:4px;border-top:1px solid rgba(168,136,232,.08)\";\n"
    "      grp.textContent = FACS_GROUP_LABELS[FACS_GROUPS.indexOf(i)] || '';\n"
    "      c.appendChild(grp);\n"
    "    }\n"
    "    const row = document.createElement('div');\n"
    "    row.style.cssText='display:flex;align-items:center;gap:6px';\n"
    "    const lbl = document.createElement('span');\n"
    "    lbl.style.cssText=\"font-size:6px;letter-spacing:.5px;color:rgba(221,213,197,.25);font-family:'JetBrains Mono',monospace;width:90px;flex-shrink:0;text-align:right\";\n"
    "    lbl.textContent = name;\n"
    "    const sl = document.createElement('input');\n"
    "    sl.type='range'; sl.min=0; sl.max=1; sl.step=.01; sl.value=0;\n"
    "    sl.style.cssText='flex:1;accent-color:#7860c8;height:2px';\n"
    "    const vl = document.createElement('span');\n"
    "    vl.style.cssText=\"font-size:6.5px;color:rgba(168,136,232,.5);font-family:'JetBrains Mono',monospace;width:28px;text-align:right;flex-shrink:0\";\n"
    "    vl.textContent='0.00';\n"
    "    sl.addEventListener('input', () => {\n"
    "      faceWeights[i] = parseFloat(sl.value);\n"
    "      vl.textContent = (+sl.value).toFixed(2);\n"
    "      if (!faceBuilt) return;\n"
    "      clearTimeout(faceTimer);\n"
    "      faceTimer = setTimeout(sendFaceExpression, 80);\n"
    "    });\n"
    "    row.appendChild(lbl); row.appendChild(sl); row.appendChild(vl);\n"
    "    c.appendChild(row);\n"
    "  });\n"
    "}\n"
    "\n"
    "function sendFaceExpression() {\n"
    "  if (!faceBuilt) return;\n"
    "  const arr = Array.from(faceWeights).map(v=>+v.toFixed(3));\n"
    "  wsSend(JSON.stringify({cmd:'rigart_face_expression',weights:arr}));\n"
    "}\n"
    "\n"
    "function wsSend(msg) {\n"
    "  if (typeof ws !== 'undefined' && ws && ws.readyState === WebSocket.OPEN) {\n"
    "    ws.send(msg);\n"
    "  }\n"
    "}\n"
    "\n"
    "function setFaceStatus(ok, txt, phi) {\n"
    "  const dot  = document.getElementById('rv3d-face-dot');\n"
    "  const stat = document.getElementById('rv3d-face-stat');\n"
    "  const phiE = document.getElementById('rv3d-face-phi');\n"
    "  if (dot)  { dot.style.background = ok ? '#a888e8' : 'rgba(255,255,255,.12)';\n"
    "               dot.style.boxShadow  = ok ? '0 0 8px rgba(168,136,232,.6)' : 'none'; }\n"
    "  if (stat) stat.textContent = txt;\n"
    "  if (phiE && phi != null) phiE.textContent = 'φ_err=' + phi.toFixed(6);\n"
    "}\n"
    "\n"
    "function showFaceResult(data) {\n"
    "  const el   = document.getElementById('rv3d-face-result');\n"
    "  const pre  = document.getElementById('rv3d-face-json');\n"
    "  if (el)  el.style.display = 'block';\n"
    "  if (pre) pre.textContent  = JSON.stringify(data, null, 2);\n"
    "}\n"
    "\n"
    "// Inject sliders\n"
    "const cranialEl = document.getElementById('rv3d-face-cranial');\n"
    "const ethnoEl   = document.getElementById('rv3d-face-ethno');\n"
    "if (cranialEl) makeFaceSlider(cranialEl, CRANIAL);\n"
    "if (ethnoEl)   makeFaceSlider(ethnoEl,   ETHNO);\n"
    "makeFacsSliders();\n"
    "\n"
    "// Subdiv slider\n"
    "const sdSl = document.getElementById('rv3d-face-subdiv');\n"
    "const sdVl = document.getElementById('rv3d-face-subdiv-v');\n"
    "const SUBDIV_V={2:'642v',3:'2562v',4:'10242v',5:'40962v'};\n"
    "  if (sdSl) sdSl.addEventListener('input', () => { if(sdVl) sdVl.textContent=sdSl.value+'→'+(SUBDIV_V[sdSl.value]||'?'); });\n"
    "\n"
    "// ── Botón BUILD ───────────────────────────────────────────────\n"
    "const buildBtn = document.getElementById('rv3d-face-build-btn');\n"
    "if (buildBtn) buildBtn.addEventListener('click', () => {\n"
    "  const subdiv = parseInt(document.getElementById('rv3d-face-subdiv')?.value || '3');\n"
    "  setFaceStatus(false, 'CONSTRUYENDO…', null);\n"
    "  buildBtn.textContent = '⟳ BUILD…';\n"
    "  buildBtn.disabled = true;\n"
    "  wsSend(JSON.stringify({\n"
    "    cmd: 'rigart_face_build',\n"
    "    subdiv,\n"
    "    build_neck:     document.getElementById('rv3d-face-neck')?.checked    ?? true,\n"
    "    build_skeleton: document.getElementById('rv3d-face-skel')?.checked    ?? true,\n"
    "    build_shapes:   document.getElementById('rv3d-face-shapes')?.checked  ?? true,\n"
    "    cranium_width:  faceParams.cranium_width  || .19,\n"
    "    cranium_height: faceParams.cranium_height || .17,\n"
    "    cranium_depth:  faceParams.cranium_depth  || .19,\n"
    "    face_phi_ratio: faceParams.face_phi_ratio || PHI,\n"
    "    interocular_dist:   faceParams.interocular_dist   || .065,\n"
    "    eye_width:          faceParams.eye_width          || .03,\n"
    "    orbital_depth:      faceParams.orbital_depth      || .018,\n"
    "    brow_protrusion:    faceParams.brow_protrusion    || .007,\n"
    "    nose_length:        faceParams.nose_length        || .052,\n"
    "    nose_width:         faceParams.nose_width         || .035,\n"
    "    nasal_tip_proj:     faceParams.nasal_tip_proj     || .018,\n"
    "    mouth_width:        faceParams.mouth_width        || .05,\n"
    "    lip_thickness_upper:faceParams.lip_thickness_upper|| .008,\n"
    "    lip_thickness_lower:faceParams.lip_thickness_lower|| .010,\n"
    "    jaw_width:          faceParams.jaw_width          || .14,\n"
    "    jaw_angle:          faceParams.jaw_angle          || 125,\n"
    "    chin_projection:    faceParams.chin_projection    || .012,\n"
    "    zygomatic_width:    faceParams.zygomatic_width    || .15,\n"
    "    zygomatic_height:   faceParams.zygomatic_height   || .06,\n"
    "    neck_width:         faceParams.neck_width         || .095,\n"
    "    neck_length:        faceParams.neck_length        || .10,\n"
    "    melanin:           faceParams.melanin            || .35,\n"
    "    hemoglobin:        faceParams.hemoglobin         || .5,\n"
    "    carotene_concentration: faceParams.carotene_concentration || .15,\n"
    "    age_factor:        faceParams.age_factor         || .2,\n"
    "    gender_factor:     faceParams.gender_factor      || .5,\n"
    "  }));\n"
    "});\n"
    "\n"
    "// ── Botón VBO ─────────────────────────────────────────────────\n"
    "const vboBtn = document.getElementById('rv3d-face-vbo-btn');\n"
    "if (vboBtn) vboBtn.addEventListener('click', () => {\n"
    "  wsSend(JSON.stringify({cmd:'rigart_face_vbo'}));\n"
    "});\n"
    "\n"
    "// ── Botón GLSL ────────────────────────────────────────────────\n"
    "const glslBtn = document.getElementById('rv3d-face-glsl-btn');\n"
    "if (glslBtn) glslBtn.addEventListener('click', () => {\n"
    "  wsSend(JSON.stringify({cmd:'rigart_face_glsl'}));\n"
    "});\n"
    "\n"
    "// ── Botón → VISOR ─────────────────────────────────────────────\n"
    "// Pide el VBO y si está disponible lo renderiza con el stride 15 del face engine\n"
    "const renderBtn = document.getElementById('rv3d-face-render-btn');\n"
    "if (renderBtn) renderBtn.addEventListener('click', () => {\n"
    "  if (!faceBuilt) { rv3dToast('Build primero'); return; }\n"
    "  rv3dToast('Face mesh activo en visor (stride 15) ✓');\n"
    "  // Solicitar geometría vía VBO info + marcar modo face en el visor\n"
    "  if (typeof setMatOverride === 'function') setMatOverride('face_pbr');\n"
    "  wsSend(JSON.stringify({cmd:'rigart_face_vbo'}));\n"
    "});\n"
    "\n"
    "// ── Receptor WS para eventos §36 ─────────────────────────────\n"
    "// Hook sobre el handler genérico existente\n"
    "const origHookFace = window._rv3dHookWsMessage;\n"
    "window._rv3dHookWsMessage = function(data) {\n"
    "  if (origHookFace && origHookFace(data)) return true;\n"
    "  try {\n"
    "    const msg = JSON.parse(data);\n"
    "    if (msg.cmd === 'rigart_face_build' || msg.ev === 'rigart_face_build' || msg.ev === 'rigart_face_result') {\n"
    "      const buildBtn2 = document.getElementById('rv3d-face-build-btn');\n"
    "      if (buildBtn2) { buildBtn2.textContent = '◈ BUILD'; buildBtn2.disabled = false; }\n"
    "      if (msg.ok) {\n"
    "        faceBuilt = true;\n"
    "        setFaceStatus(true,\n"
    "          `${msg.verts}v · ${msg.tris}t · subdiv${msg.subdiv} · ${msg.skeleton?'DQ':'–'} · ${msg.shapes?'FACS52':'–'}`,\n"
    "          msg.phi_error);\n"
    "        showFaceResult(msg);\n"
    "        rv3dToast('Face mesh §36 construido ✓');\n"
    "      } else {\n"
    "        faceBuilt = false;\n"
    "        setFaceStatus(false, 'ERROR: ' + (msg.error||'?'), null);\n"
    "        rv3dToast('Face build error: ' + (msg.error||'?'));\n"
    "      }\n"
    "      return true;\n"
    "    }\n"
    "    if (msg.cmd === 'rigart_face_expression') {\n"
    "      if (msg.ok) rv3dToast('Expresión FACS aplicada ✓');\n"
    "      return true;\n"
    "    }\n"
    "    if (msg.cmd === 'rigart_face_vbo' || msg.cmd === 'rigart_face_glsl') {\n"
    "      showFaceResult(msg);\n"
    "      return true;\n"
    "    }\n"
    "  } catch(e) {}\n"
    "  return false;\n"
    "};\n"
    "\n"
    "// Toggle panel width for face tab (need more height)\n"
    "document.getElementById('rv3d-panel-body')?.style &&\n"
    "  (()=>{\n"
    "    // When face tab is clicked, expand panel height\n"
    "    const faceTab = document.querySelector('[data-rv3d-tab=\"face\"]');\n"
    "    if (faceTab) faceTab.addEventListener('click', () => {\n"
    "      const pb = document.getElementById('rv3d-panel-body');\n"
    "      if (pb) pb.style.maxHeight = '580px';\n"
    "    });\n"
    "    // Other tabs reset height\n"
    "    document.querySelectorAll('.rv3d-ptab:not([data-rv3d-tab=\"face\"])').forEach(t => {\n"
    "      t.addEventListener('click', () => {\n"
    "        const pb = document.getElementById('rv3d-panel-body');\n"
    "        if (pb) pb.style.maxHeight = '';\n"
    "      });\n"
    "    });\n"
    "  })();\n"
    "\n"
    "})(); // end §36 Face Engine panel IIFE\n"
    "\n"
    "</script>\n"
    "</body></html>\n";


/* ═══════════════════════════════════════════════════════════════════════════
 * API PÚBLICA
 * ═══════════════════════════════════════════════════════════════════════════ */

/* Arranca el túnel UI único en el puerto indicado. Bloquea hasta stop. */
int rigcom_ui_serve(rl_u16 port) {
    if (g_ui_active) {
        rig_log_warn("[rigcom_ui] túnel ya activo — ignorando segundo serve\n");
        return -1;
    }
    (void)rig_ws_server_set_embedded_dashboard(RIGCOM_UI_HTML, sizeof(RIGCOM_UI_HTML) - 1);
    int rc = rig_ws_server_init(&g_ui_server, port);
    if (rc != 0) {
        rig_log_error("[rigcom_ui] rig_ws_server_init fallo rc=%d puerto=%u\n",
                      rc, (unsigned)port);
        return rc;
    }
    g_ui_active = &g_ui_server;
    rig_log_info("[rigcom_ui] RigCom Visor 3D Pro activo en :%u — piel viva servida\n",
                 (unsigned)port);
    rc = rig_ws_server_run(&g_ui_server);
    g_ui_active = 0;
    return rc;
}

int rigcom_ui_stop(void) {
    if (!g_ui_active) return 0;
    int rc = rig_ws_server_stop(g_ui_active);
    g_ui_active = 0;
    return rc;
}

int rigcom_ui_is_active(void) { return g_ui_active ? 1 : 0; }

int rigcom_ui_publish(const char *json, rl_size len) {
    if (!g_ui_active || !json || !len) return 0;
    return rig_ws_broadcast(g_ui_active, json, len);
}

int rigcom_ui_send_to(int fd, const char *json, rl_size len) {
    if (!g_ui_active || !json || !len) return 0;
    return rig_ws_send_to_fd(g_ui_active, fd, json, len) ? 0 : -1;
}

/* ═══════════════════════════════════════════════════════════════════════════
 * Contrato JSON canónico
 * ═══════════════════════════════════════════════════════════════════════════ */
static void emit_escape(char **p, char *end, const char *s) {
    if (!s) return;
    for (; *s && *p < end; s++) {
        unsigned char c = (unsigned char)*s;
        if (c == '"' || c == '\\') {
            if (*p + 2 <= end) { *(*p)++ = '\\'; *(*p)++ = (char)c; }
        } else if (c == '\n') { if (*p + 2 <= end) { *(*p)++ = '\\'; *(*p)++ = 'n'; } }
        else if (c == '\r')   { if (*p + 2 <= end) { *(*p)++ = '\\'; *(*p)++ = 'r'; } }
        else if (c == '\t')   { if (*p + 2 <= end) { *(*p)++ = '\\'; *(*p)++ = 't'; } }
        else if (c < 0x20) {
            if (*p + 6 <= end) {
                static const char hex[] = "0123456789abcdef";
                *(*p)++ = '\\'; *(*p)++ = 'u'; *(*p)++ = '0'; *(*p)++ = '0';
                *(*p)++ = hex[(c >> 4) & 0xF]; *(*p)++ = hex[c & 0xF];
            }
        } else { *(*p)++ = (char)c; }
    }
}

static void emit_field_str(char **p, char *end, const char *key, const char *val) {
    if (!val) return;
    for (const char *k = ",\""; *k && *p < end; k++) *(*p)++ = *k;
    for (const char *k = key; *k && *p < end; k++) *(*p)++ = *k;
    for (const char *k = "\":\""; *k && *p < end; k++) *(*p)++ = *k;
    emit_escape(p, end, val);
    if (*p < end) *(*p)++ = '"';
}

int rigcom_ui_emit_event(
    const char *type,
    const char *module,
    const char *subsystem,
    const char *group,
    const char *symbol,
    const char *label,
    const char *value,
    const char *source_file,
    const char *source_function,
    int         source_line,
    const char *ui_surface,
    const char *severity)
{
    if (!g_ui_active) return 0;

    char buf[2048];
    char *p = buf, *end = buf + sizeof(buf);

    for (const char *k = "{\"type\":\""; *k && p < end; k++) *p++ = *k;
    emit_escape(&p, end, type ? type : "evento");
    if (p < end) *p++ = '"';

    emit_field_str(&p, end, "module",          module          ? module          : "?");
    emit_field_str(&p, end, "subsystem",       subsystem       ? subsystem       : "-");
    emit_field_str(&p, end, "group",           group           ? group           : "-");
    emit_field_str(&p, end, "symbol",          symbol          ? symbol          : "-");
    emit_field_str(&p, end, "label",           label           ? label           : "");
    if (value) emit_field_str(&p, end, "value", value);
    emit_field_str(&p, end, "source_file",     source_file     ? source_file     : "?");
    emit_field_str(&p, end, "source_function", source_function ? source_function : "?");

    for (const char *k = ",\"source_line\":"; *k && p < end; k++) *p++ = *k;
    char num[16]; int n = 0; int neg = source_line < 0 ? 1 : 0;
    unsigned v = (unsigned)(neg ? -source_line : source_line);
    do { num[n++] = (char)('0' + (v % 10)); v /= 10; } while (v && n < (int)sizeof(num));
    if (neg && p < end) *p++ = '-';
    while (n-- > 0 && p < end) *p++ = num[n];

    emit_field_str(&p, end, "ui_surface", ui_surface ? ui_surface : "-");
    emit_field_str(&p, end, "severity",   severity   ? severity   : "info");

    for (const char *k = ",\"visible\":true}"; *k && p < end; k++) *p++ = *k;

    return rigcom_ui_publish(buf, (rl_size)(p - buf));
}
